const e=[{id:"sv-4-316",phase:4,topic:"4.1.1",qtype:"concept",difficulty:1,stem:"What is the main purpose of a **linear correlation analysis**?",options:["To give an equation that predicts Y for any chosen value of X","To prove that changes in X cause the changes seen in Y","To compare the means of two independent groups","To measure the strength of the linear association between two continuous variables"],answer:3,hint:"Correlation answers one question only: how tightly do X and Y move together in a straight line?",steps:[{title:"Key idea",body:"The book: the main purpose of linear correlation is to **measure the strength of the linear association** between X and Y."},{title:"Eliminate look-alikes",body:"Equation = regression; cause = DOE; group means = t-test."}],final:"Correlation = strength of linear association → answer **D**",whyWrong:["Incorrect — a prediction equation Y = f(X) is the output of regression, not correlation.","Incorrect — cause and effect needs a designed experiment; correlation only shows association.","Incorrect — comparing two group means is the job of a 2-sample t-test.",""],bookRef:"Book pp. 428–432"},{id:"sv-4-317",phase:4,topic:"4.1.1",qtype:"concept",difficulty:1,stem:"What range of values can the Pearson correlation coefficient **r** take?",options:["From 0 to 1","From −1 to +1","From 0% to 100%","Any value from minus infinity to plus infinity"],answer:1,hint:"r carries both a sign and a size, and the size is capped.",steps:[{title:"Key idea",body:"r runs from **−1** (perfect negative line) through **0** (no linear relationship) to **+1** (perfect positive line)."},{title:"Eliminate look-alikes",body:"0–1 and 0–100% describe R-sq; an unbounded range describes a slope."}],final:"r lies between −1 and +1 → answer **B**",whyWrong:["Incorrect — 0 to 1 ignores negative relationships; it describes |r| or R-sq written as a fraction.","","Incorrect — 0% to 100% is the range of R-sq, the share of variation explained.","Incorrect — an unlimited range belongs to the regression slope, which depends on the units."],bookRef:"Book pp. 428–432"},{id:"sv-4-318",phase:4,topic:"4.1.1",qtype:"concept",difficulty:1,stem:"What does the **sign** (+ or −) of a correlation coefficient tell the team?",options:["How tightly the points cluster around a straight line","Whether the correlation is statistically significant","How many units Y changes for each unit change in X","The direction in which Y tends to move as X increases"],answer:3,hint:"Split r into two parts: sign and size.",steps:[{title:"Key idea",body:"**Sign = direction** (positive: Y rises with X; negative: Y falls as X rises). **Size = strength**."},{title:"Eliminate look-alikes",body:"Strength = |r|, significance = P-Value, units of change = slope."}],final:"Sign of r = direction → answer **D**",whyWrong:["Incorrect — tightness is the strength, read from the size of |r|, not its sign.","Incorrect — significance is judged from the P-Value compared with α.","Incorrect — change in Y per unit of X is the regression slope.",""],bookRef:"Book pp. 428–432"},{id:"sv-4-319",phase:4,topic:"4.1.1",qtype:"concept",difficulty:2,stem:"A Black Belt sets up a significance test for the Pearson correlation between **dwell time** and **picking errors**. What is the **alternative hypothesis (Hₐ)**?",options:["The population correlation coefficient is equal to zero","The sample correlation coefficient is greater than 0.80","The slope of the fitted line is equal to one","The population correlation coefficient is not equal to zero"],answer:3,hint:"The null is always 'nothing going on'; the alternative is the opposite.",steps:[{title:"Key idea",body:"Correlation test: **H₀: ρ = 0** (no correlation), **Hₐ: ρ ≠ 0** (correlation exists)."},{title:"Eliminate look-alikes",body:"0.80 is a practical rule of thumb; slope hypotheses belong to regression."}],final:"Hₐ: ρ ≠ 0 → answer **D**",whyWrong:["Incorrect — ρ = 0 (no correlation) is the null hypothesis, the claim the test tries to reject.","Incorrect — 0.80 is the book's practical-significance guideline, not a hypothesis about the population.","Incorrect — hypotheses about a slope belong to regression, and the tested value is zero, not one.",""],bookRef:"Book pp. 428–432"},{id:"sv-4-320",phase:4,topic:"4.1.1",qtype:"concept",difficulty:2,stem:"From 1,200 hotel bookings, a Black Belt finds **r = −0.15** with **P-Value = 0.003** between **booking lead time** and **guest rating** (α = 0.05). How should the result be described?",options:["Practically significant but not statistically significant","Statistically significant but not practically significant","Both statistically and practically significant","Neither statistically nor practically significant"],answer:1,hint:"Judge statistical significance from p and practical significance from |r|.",steps:[{title:"Key idea",body:"Two separate checks: **p < α** → statistically significant; **|r| > 0.80** → practically significant, **|r| < 0.20** → not."},{title:"Apply to the stem",body:"p = 0.003 < 0.05 → statistically significant. |r| = 0.15 < 0.20 → not practically significant."},{title:"Eliminate look-alikes",body:"Large samples make even tiny correlations 'significant'."}],final:"Significant p, tiny |r| → answer **B**",whyWrong:["Incorrect — practical significance needs |r| above 0.80; 0.15 is below the 0.20 'not significant' guideline.","","Incorrect — |r| = 0.15 fails the book's practical guideline even though p is small.","Incorrect — p = 0.003 < 0.05, so the result is statistically significant."],bookRef:"Book pp. 430–431",trap:"With hundreds of points almost any r gives p < 0.05 — always look at |r| too."},{id:"sv-4-321",phase:4,topic:"4.1.1",qtype:"concept",difficulty:1,stem:"In correlation analysis, what is meant by **bivariate data**?",options:["Two samples taken from two independent groups","Ordered pairs of X and Y values recorded on the same unit or occasion","One characteristic measured twice by two different appraisers","Counts of items falling into two attribute categories"],answer:1,hint:"Correlation needs each X to be matched with its own Y.",steps:[{title:"Key idea",body:"The book: correlation needs **bivariate data** — ordered pairs (X, Y) where both values vary."},{title:"Eliminate look-alikes",body:"Independent groups = 2-sample test; appraisers = MSA; category counts = chi-square."}],final:"Bivariate = paired X–Y data → answer **B**",whyWrong:["Incorrect — two independent groups are compared with a 2-sample test, not correlated as pairs.","","Incorrect — repeated measurements by appraisers belong to a Gage R&R study.","Incorrect — counts in categories are attribute data analysed with a chi-square test."],bookRef:"Book pp. 428–432"},{id:"sv-4-322",phase:4,topic:"4.1.1",qtype:"concept",difficulty:2,stem:"How does the book classify a correlation study carried out on existing process records?",options:["It is a designed experiment with controlled factor levels","It is a pilot that tests the proposed solution on a small scale","It is a measurement system study of the data collection method","It analyses historical data and is not a form of experimentation"],answer:3,hint:"Did anyone deliberately change X? If not, it is passive data.",steps:[{title:"Key idea",body:"Correlation uses **historical** (passive) process data. The book stresses it is **not a form of experimentation**."},{title:"Eliminate look-alikes",body:"DOE changes X on purpose; a pilot tests a solution; MSA checks measurement."}],final:"Correlation = historical, not an experiment → answer **D**",whyWrong:["Incorrect — a designed experiment deliberately changes X; correlation only observes what already happened.","Incorrect — a pilot belongs to the Improve phase solution trial, not to correlation.","Incorrect — a measurement system study (MSA) checks the gauge, not the X–Y relationship.",""],bookRef:"Book p. 447"},{id:"sv-4-323",phase:4,topic:"4.1.1",qtype:"concept",difficulty:2,stem:"Which correlation coefficient shows the **strongest** linear relationship?",options:["−0.91","−0.45","+0.08","+0.62"],answer:0,hint:"Strength is the size of r, whatever its sign.",steps:[{title:"Key idea",body:"Ignore the sign and compare **|r|**: the larger, the stronger."},{title:"Apply to the stem",body:"|−0.91| is the largest of the four values."},{title:"Eliminate look-alikes",body:"A negative sign shows direction, not weakness."}],final:"|−0.91| is largest → answer **A**",whyWrong:["","Incorrect — |−0.45| is moderate; it is weaker than |−0.91|.","Incorrect — +0.08 is close to zero, almost no linear relationship.","Incorrect — +0.62 is the largest positive value, but its size is smaller than 0.91."],bookRef:"Book pp. 428–432",trap:"Do not pick the largest positive number — a negative r can be the strongest."},{id:"sv-4-324",phase:4,topic:"4.1.1",qtype:"concept",difficulty:2,stem:"Why does the book make a **scatter plot** before calculating r?",options:["To check whether the Y data follow a normal distribution","To show how often each value of Y occurs","To display how the process changes over time","To see the shape of the relationship, including curves or outliers that r can hide"],answer:3,hint:"Which graph shows X against Y?",steps:[{title:"Key idea",body:"The book's order is **scatter plot → correlation → regression**. The picture shows curves, clusters and outliers."},{title:"Eliminate look-alikes",body:"Probability plot = normality; histogram = frequency; run chart = time order."}],final:"Scatter plot shows the shape first → answer **D**",whyWrong:["Incorrect — normality of one variable is checked with a probability plot or normality test.","Incorrect — the frequency of values is shown by a histogram.","Incorrect — change over time is shown by a run chart or control chart.",""],bookRef:"Book pp. 428–432"},{id:"sv-4-325",phase:4,topic:"4.1.1",qtype:"concept",difficulty:1,stem:"What does the sample correlation coefficient **r** estimate?",options:["The slope of the population regression line","The population correlation coefficient ρ","The proportion of variation in Y explained by X","The standard deviation of the prediction errors"],answer:1,hint:"Sample statistic estimates the matching population parameter.",steps:[{title:"Key idea",body:"r is a **sample statistic**; it estimates the **population** correlation coefficient (written ρ, or R in the book)."},{title:"Eliminate look-alikes",body:"Slope → b₁; proportion explained → R-sq; error SD → S."}],final:"r estimates ρ → answer **B**",whyWrong:["Incorrect — the population slope is estimated by the regression coefficient b₁.","","Incorrect — the proportion explained is R-sq.","Incorrect — the standard deviation of the errors is S in the regression output."],bookRef:"Book pp. 428–432"},{id:"sv-4-326",phase:4,topic:"4.1.1",qtype:"concept",difficulty:2,stem:"A strong correlation (r = 0.84) is found between **spindle speed** and **surface roughness** in two years of production records. How can the team prove that speed **causes** the roughness?",options:["By adding more historical records until the P-Value reaches 0.000","By running a designed experiment that changes speed while holding other factors constant","By confirming that |r| is above the 0.80 practical guideline","By fitting a regression line and checking that R-sq is high"],answer:1,hint:"Only deliberately changing X can show cause and effect.",steps:[{title:"Key idea",body:"The book: correlation does **not** prove causation; a **designed experiment (DOE)** is needed."},{title:"Eliminate look-alikes",body:"Bigger samples, larger |r| and high R-sq all describe association only."}],final:"Causation needs DOE → answer **B**",whyWrong:["Incorrect — more passive data sharpens the estimate of r but still cannot exclude lurking variables.","","Incorrect — |r| above 0.80 shows practical strength of association, not cause.","Incorrect — regression on the same historical data still shows only association."],bookRef:"Book p. 431"},{id:"sv-4-327",phase:4,topic:"4.1.1",qtype:"concept",difficulty:1,stem:"What does a correlation coefficient of **r = +1** mean?",options:["Y increases by exactly one unit for each one-unit increase in X","X explains exactly 1% of the variation in Y","All points lie exactly on a straight line that rises from left to right","Changes in X are proven to cause changes in Y"],answer:2,hint:"+1 is the upper limit of r.",steps:[{title:"Key idea",body:"r = +1 is a **perfect positive linear** relationship: every point is on one upward line."},{title:"Eliminate look-alikes",body:"r says nothing about the slope value and never proves cause."}],final:"r = +1: perfect positive line → answer **C**",whyWrong:["Incorrect — a change of one unit per unit is a slope of 1, which r does not measure.","Incorrect — r = +1 means R-sq = 100%, not 1%.","","Incorrect — even a perfect correlation does not prove cause and effect."],bookRef:"Book pp. 428–432"},{id:"sv-4-328",phase:4,topic:"4.1.1",qtype:"concept",difficulty:3,stem:"A Black Belt correlates **delivery time** with **distance**, then converts delivery time from **minutes to hours** and runs the correlation again. What happens to r?",options:["It becomes 60 times smaller","It becomes 60 times larger","It changes from positive to negative","It stays the same"],answer:3,hint:"r is a unit-free number between −1 and +1.",steps:[{title:"Key idea",body:"r is **unit-free**: a change of units (minutes → hours, °C → °F) leaves it unchanged."},{title:"Eliminate look-alikes",body:"The regression **slope** depends on units; r does not."}],final:"Units do not change r → answer **D**",whyWrong:["Incorrect — r has no units, so rescaling Y does not shrink it; the slope would change instead.","Incorrect — r cannot grow with a unit change and is capped at ±1 anyway.","Incorrect — dividing by a positive constant keeps the direction of the relationship.",""],bookRef:"Book pp. 428–432",trap:"Do not confuse r with the slope — only the slope changes with units."},{id:"sv-4-329",phase:4,topic:"4.1.1",qtype:"concept",difficulty:1,stem:"What is meant by the **strength** of a linear correlation?",options:["How closely the points cluster around a straight line","How steep the straight line through the points is","Where the line crosses the Y axis","How many paired points were collected"],answer:0,hint:"Think of a tight band versus a wide cloud.",steps:[{title:"Key idea",body:"The book: how tightly the (X, Y) points follow the straight-line path is the **strength**."},{title:"Eliminate look-alikes",body:"Steepness = slope, crossing point = intercept, number of pairs = sample size."}],final:"Strength = tightness around the line → answer **A**",whyWrong:["","Incorrect — steepness is the slope; two lines with very different slopes can have the same r.","Incorrect — the crossing point on the Y axis is the intercept of a regression line.","Incorrect — the number of pairs affects the P-Value, not the strength."],bookRef:"Book pp. 428–432"},{id:"sv-4-330",phase:4,topic:"4.1.1",qtype:"concept",difficulty:2,stem:"Why can a **weak** correlation still give a very small P-Value?",options:["The P-Value depends only on the sign of r","With a large sample, even a weak correlation is unlikely to be due to chance","A weak correlation is always practically significant","The P-Value measures the strength of the relationship"],answer:1,hint:"The P-Value depends on both r and n.",steps:[{title:"Key idea",body:"The P-Value tests H₀: ρ = 0. As **n grows**, smaller values of r become statistically significant."},{title:"Eliminate look-alikes",body:"Strength is read from |r|; practical value needs |r| > 0.80."}],final:"Large n makes weak r significant → answer **B**",whyWrong:["Incorrect — a negative and a positive r of the same size give the same P-Value.","","Incorrect — the book's guideline says |r| below 0.20 is not practically significant.","Incorrect — strength is |r|; the P-Value only says whether r differs from zero."],bookRef:"Book pp. 430–431"},{id:"sv-4-331",phase:4,topic:"4.1.1",qtype:"concept",difficulty:2,stem:"Which statement about the correlation coefficient r is CORRECT?",options:["A value of 0.60 means Y rises 0.60 units for each unit of X","A value of 0 proves that X and Y are unrelated in any way","A value of −0.88 shows a strong linear relationship","A value is only meaningful when it is positive"],answer:2,hint:"Separate sign, size and what r does not measure.",steps:[{title:"Key idea",body:"|r| gives strength, the sign gives direction. |−0.88| is above 0.80, so it is strong."},{title:"Eliminate look-alikes",body:"r is not a slope, r = 0 does not exclude curves, and negative r is valid."}],final:"−0.88 is strong → answer **C**",whyWrong:["Incorrect — change in Y per unit X is the regression slope, not r.","Incorrect — r = 0 rules out only a straight-line relationship; a curve can still exist.","","Incorrect — negative values are just as meaningful; the sign gives direction."],bookRef:"Book pp. 428–432"},{id:"sv-4-332",phase:4,topic:"4.1.1",qtype:"concept",difficulty:2,stem:"Which statement about correlation and regression is CORRECT?",options:["Regression should be completed before correlation is checked","Correlation proves cause and effect when the P-Value is below 0.05","Correlation and regression both require attribute data","Correlation gives the strength of a relationship; regression gives a prediction equation"],answer:3,hint:"Book quote: correlation ONLY tells us the strength of a relationship.",steps:[{title:"Key idea",body:"Correlation = **strength**; regression = **mathematical relationship / prediction model**."},{title:"Eliminate look-alikes",body:"Order is correlation first; neither proves cause; both use continuous data."}],final:"Correlation = strength, regression = equation → answer **D**",whyWrong:["Incorrect — the book's order is scatter plot, then correlation, then regression.","Incorrect — a small P-Value shows a real association, never proof of cause.","Incorrect — both tools need continuous X and Y data.",""],bookRef:"Book pp. 432–433"},{id:"sv-4-333",phase:4,topic:"4.1.1",qtype:"concept",difficulty:3,stem:"Which statement about **outliers** in correlation analysis is CORRECT?",options:["A single extreme point can create or hide a strong correlation","Outliers change the P-Value but never the value of r","Pearson r is unaffected by outliers because it is based on ranks","Outliers matter only when the sample has more than 100 points"],answer:0,hint:"r uses squared deviations from the mean — what does one far-away point do?",steps:[{title:"Key idea",body:"Pearson r is built from deviations from the means, so **one extreme point** can pull r up or down sharply."},{title:"Eliminate look-alikes",body:"This is why the book plots the scatter diagram before trusting r."}],final:"One point can make or break r → answer **A**",whyWrong:["","Incorrect — r itself is calculated from the deviations, so an extreme point changes it directly.","Incorrect — Pearson r uses the actual values; rank-based correlation is a different method.","Incorrect — outliers matter most in small samples, where one point carries more weight."],bookRef:"Book pp. 428–432"},{id:"sv-4-334",phase:4,topic:"4.1.1",qtype:"concept",difficulty:3,stem:"Which statement about r and R-sq in a simple linear regression is TRUE?",options:["r and R-sq always have the same numerical value","R-sq is the square of r, so it cannot be negative","R-sq keeps the sign of r to show direction","r is the percentage of variation in Y explained by X"],answer:1,hint:"In simple linear regression the two are linked by squaring.",steps:[{title:"Key idea",body:"With one X, **R-sq = r²**. A square is never negative, so R-sq loses the direction."},{title:"Eliminate look-alikes",body:"r keeps the sign; R-sq is the share of variation explained."}],final:"R-sq = r², never negative → answer **B**",whyWrong:["Incorrect — they are equal only at 0 or ±1; otherwise squaring makes R-sq smaller than |r|.","","Incorrect — squaring removes the sign; direction must be read from r or the slope.","Incorrect — the percentage of variation explained is R-sq, not r."],bookRef:"Book pp. 428–432"},{id:"sv-4-335",phase:4,topic:"4.1.1",qtype:"concept",difficulty:3,stem:"Which statement about sampling a **narrow range of X** is CORRECT?",options:["It always makes the correlation coefficient larger","It has no effect on r because r has no units","It can make a real relationship look weak or absent","It proves that the relationship is non-linear"],answer:2,hint:"Correlation needs both variables to vary.",steps:[{title:"Key idea",body:"If X barely varies, the trend is buried in noise, so |r| shrinks — a **restricted-range** effect."},{title:"Eliminate look-alikes",body:"Unit-free is about scale, not spread; curvature is a separate question."}],final:"Narrow X range hides a relationship → answer **C**",whyWrong:["Incorrect — restricting the range usually lowers |r|, because X varies too little to show the trend.","Incorrect — being unit-free does not protect r from a lack of spread in X.","","Incorrect — a narrow range hides the pattern; it says nothing about curvature."],bookRef:"Book pp. 428–432"},{id:"sv-4-336",phase:4,topic:"4.1.1",qtype:"statements",difficulty:2,stem:`Which statements about the Pearson correlation coefficient are CORRECT?

1. It measures the strength of a linear association.
2. Its value always lies between −1 and +1.
3. It shows how much Y changes for each unit of X.
4. A value near zero proves that X and Y are unrelated.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Check each statement against what r measures and what it does not.",steps:[{title:"Key idea",body:"1 is the book's definition; 2 is the range of r. Both true."},{title:"Eliminate look-alikes",body:"3 = slope (regression). 4 is false: a U-shaped curve can give r ≈ 0."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 2 is true, but statement 3 describes the regression slope.","Incorrect — statement 3 describes the slope and statement 4 ignores curved relationships.","Incorrect — statement 1 is true, but r near zero excludes only a straight-line relationship."],bookRef:"Book pp. 428–432"},{id:"sv-4-337",phase:4,topic:"4.1.1",qtype:"statements",difficulty:2,stem:`Which statements about correlation and causation are CORRECT?

1. A strong correlation proves that X causes Y.
2. A lurking variable can produce a strong correlation.
3. A designed experiment is needed to establish cause and effect.
4. A significant correlation justifies changing X at once.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:1,hint:"Which statements respect 'correlation is not causation'?",steps:[{title:"Key idea",body:"Correlation shows association only. A third (**lurking**) variable may drive both X and Y."},{title:"Apply to the stem",body:"2 and 3 are true. 1 and 4 treat association as cause."}],final:"Statements 2 and 3 → answer **B**",whyWrong:["Incorrect — statement 2 is true, but statement 1 claims proof of cause, which correlation cannot give.","","Incorrect — statement 3 is true, but statement 4 acts on association without proving cause.","Incorrect — both statements 1 and 4 treat correlation as proof of cause."],bookRef:"Book p. 431"},{id:"sv-4-338",phase:4,topic:"4.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Correlation measures the strength of the [?] association between two continuous variables.`,options:["causal","exponential","linear","quadratic"],answer:2,hint:"Pearson r is tied to one shape of relationship.",steps:[{title:"Key idea",body:"The book: correlation measures the strength of the **linear** association between X and Y."},{title:"Eliminate look-alikes",body:"Curved shapes need regression models; cause needs DOE."}],final:"linear → answer **C**",whyWrong:["Incorrect — correlation never shows cause; that needs a designed experiment.","Incorrect — exponential relationships are fitted with a non-linear regression model.","","Incorrect — a quadratic curve is a 2nd-order regression model; r can miss it."],bookRef:"Book pp. 428–432"},{id:"sv-4-339",phase:4,topic:"4.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

A third factor that drives both X and Y, producing a misleading correlation between them, is called a [?] variable.`,options:["dependent","independent","lurking","response"],answer:2,hint:"It hides behind the X–Y pair.",steps:[{title:"Key idea",body:"A **lurking** (hidden) variable moves X and Y together, so they correlate without a causal link."},{title:"Eliminate look-alikes",body:"Dependent and response = Y; independent = X."}],final:"lurking → answer **C**",whyWrong:["Incorrect — the dependent variable is Y, the output being studied.","Incorrect — the independent variable is X, the input being studied.","","Incorrect — response is another name for the output Y."],bookRef:"Book p. 431"},{id:"sv-4-340",phase:4,topic:"4.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

In the hypothesis test for correlation, the null hypothesis states that the population correlation coefficient equals [?].`,options:["−1","0","0.80","+1"],answer:1,hint:"The null hypothesis always says 'no relationship'.",steps:[{title:"Key idea",body:"**H₀: ρ = 0** — no linear correlation in the population."},{title:"Eliminate look-alikes",body:"±1 are perfect lines; 0.80 is a rule of thumb."}],final:"0 → answer **B**",whyWrong:["Incorrect — −1 is a perfect negative line, not the 'no effect' value.","","Incorrect — 0.80 is the practical-significance guideline, not a hypothesis value.","Incorrect — +1 is a perfect positive line, not the 'no effect' value."],bookRef:"Book pp. 428–432"},{id:"sv-4-341",phase:4,topic:"4.1.1",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

If Y tends to fall as X rises, the correlation is described as [?].`,options:["negative","neutral","positive","spurious"],answer:0,hint:"Direction is given by the sign.",steps:[{title:"Key idea",body:"The book: Y tends to **fall** as X rises → **negative** correlation."},{title:"Eliminate look-alikes",body:"Rising together = positive; spurious is about cause, not direction."}],final:"negative → answer **A**",whyWrong:["","Incorrect — no definite change in Y would be no correlation, not a falling pattern.","Incorrect — positive means Y tends to rise as X rises.","Incorrect — spurious describes a correlation without a causal link, not its direction."],bookRef:"Book pp. 428–432"},{id:"sv-4-342",phase:4,topic:"4.1.1",qtype:"not-except",difficulty:2,stem:"Which conclusion can NOT be supported by a correlation analysis alone?",options:["Y tends to rise or fall as X increases","How strong the linear association between X and Y is","Whether the linear association is statistically significant","Changes in X cause the changes in Y"],answer:3,hint:"List what r and its P-Value can tell you; the odd one out is the answer.",steps:[{title:"Key idea",body:"Correlation gives **direction** (sign), **strength** (|r|) and **significance** (P-Value)."},{title:"Apply to the stem",body:"It cannot give **cause and effect** — that needs a designed experiment."}],final:"Causation is not supported → answer **D**",whyWrong:["Correct as a supported conclusion — direction is given by the sign of r, so this is not the answer.","Correct as a supported conclusion — strength is given by |r|, so this is not the answer.","Correct as a supported conclusion — the P-Value tests H₀: ρ = 0, so this is not the answer.",""],bookRef:"Book p. 431"},{id:"sv-4-343",phase:4,topic:"4.1.1",qtype:"not-except",difficulty:3,stem:"Which is NOT a reason why a correlation coefficient might mislead the team?",options:["The data were recorded as ordered X–Y pairs","A single extreme point dominates the calculation","The true relationship follows a curve","Two different groups have been pooled together"],answer:0,hint:"Three options are known traps; one is a basic requirement.",steps:[{title:"Key idea",body:"Correlation **requires** paired (bivariate) data — that is correct practice, not a problem."},{title:"Eliminate look-alikes",body:"Outliers, curves and pooled groups are the classic ways r misleads."}],final:"Paired data is a requirement, not a trap → answer **A**",whyWrong:["","A real reason — one outlier can create or destroy a correlation, so this is not the answer.","A real reason — r measures only straight-line patterns and can miss a curve, so this is not the answer.","A real reason — pooled groups (stratification) can create or hide a correlation, so this is not the answer."],bookRef:"Book pp. 428–432"},{id:"sv-4-344",phase:4,topic:"4.1.1",qtype:"not-except",difficulty:2,stem:"Which is NOT required for a Pearson correlation analysis?",options:["Paired observations of X and Y","Data from a designed experiment","Continuous measurements for both variables","Variation in both X and Y"],answer:1,hint:"Correlation is a passive, historical-data tool.",steps:[{title:"Key idea",body:"Correlation uses **historical** data; the book says it is **not** a form of experimentation."},{title:"Eliminate look-alikes",body:"Pairs, continuous data and variation in both are genuine requirements."}],final:"No DOE needed → answer **B**",whyWrong:["Required — each X must be matched with its own Y, so this is not the answer.","","Required — Pearson r is for continuous X and Y, so this is not the answer.","Required — if either variable is constant, r cannot be calculated, so this is not the answer."],bookRef:"Book pp. 428–429, 447"},{id:"sv-4-345",phase:4,topic:"4.1.1",qtype:"not-except",difficulty:2,stem:"A Black Belt reports **r = −0.84** with **P-Value = 0.000** (α = 0.05). Which statement is NOT correct?",options:["The relationship is negative","The relationship is strong by the book's practical guideline","As X increases, Y tends to increase","The null hypothesis of no correlation is rejected"],answer:2,hint:"Read the sign for direction, |r| for strength, p for the decision.",steps:[{title:"Key idea",body:"Negative r → Y tends to **decrease** as X increases."},{title:"Apply to the stem",body:"So 'Y tends to increase' is the false statement; the others are true."}],final:"Negative r means Y falls as X rises → answer **C**",whyWrong:["Correct statement — the negative sign means a negative relationship, so this is not the answer.","Correct statement — |−0.84| exceeds 0.80, so this is not the answer.","","Correct statement — p = 0.000 < 0.05, so H₀: ρ = 0 is rejected; this is not the answer."],bookRef:"Book pp. 428–432"},{id:"sv-4-346",phase:4,topic:"4.1.1",qtype:"scenario",difficulty:1,stem:"A hospital Green Belt has 40 days of paired data on **nurses on duty** and **average patient wait time (min)**. Both are continuous. She wants one number that shows how strongly the two move together in a straight line. Which analysis should she use?",options:["Chi-square test of independence","One-way ANOVA","Mann-Whitney test","Pearson correlation"],answer:3,hint:"Continuous X, continuous Y, strength of a straight-line link.",steps:[{title:"Key idea",body:"Two continuous variables in pairs + strength of linear association → **Pearson correlation**."},{title:"Eliminate look-alikes",body:"Chi-square = attribute data; ANOVA and Mann-Whitney compare groups."}],final:"Pearson correlation → answer **D**",whyWrong:["Incorrect — chi-square tests association between two attribute (count) variables.","Incorrect — one-way ANOVA compares means of three or more groups defined by a categorical X.","Incorrect — Mann-Whitney compares medians of two independent, non-normal groups.",""],bookRef:"Book pp. 428–432"},{id:"sv-4-347",phase:4,topic:"4.1.1",qtype:"scenario",difficulty:3,stem:"In an injection-moulding cell, **part shrinkage** is high at low mould temperatures, lowest in the middle of the range and high again at high temperatures. Minitab gives **r = 0.04**. What is the BEST interpretation?",options:["There is a strong curved relationship that r does not capture","Mould temperature has no effect on shrinkage","There is a weak positive linear relationship worth modelling","The measurement system must have failed"],answer:0,hint:"Pearson r only detects straight lines.",steps:[{title:"Key idea",body:"A U-shaped pattern rises and falls, so the linear fit is flat and **r ≈ 0**."},{title:"Apply to the stem",body:"The scatter plot shows a strong **non-linear** relationship; a quadratic model would be needed."},{title:"Eliminate look-alikes",body:"'No effect' ignores the curve; r = 0.04 is not a usable linear trend."}],final:"Curve hidden by r ≈ 0 → answer **A**",whyWrong:["","Incorrect — r ≈ 0 rules out only a straight-line relationship, not a curve.","Incorrect — r = 0.04 is negligible, and the pattern described is clearly curved, not linear.","Incorrect — nothing points to a gauge problem; the U shape is a real process pattern."],bookRef:"Book pp. 428–432",trap:"r = 0 means no LINEAR relationship — always look at the scatter plot."},{id:"sv-4-348",phase:4,topic:"4.1.1",qtype:"scenario",difficulty:2,stem:"Over 60 days in a city hospital, the **number of staff on duty** and the **number of medication incidents** give **r = 0.89** (p < 0.001). Busy days have both more staff and more incidents. What is this MOST likely an example of?",options:["Proof that adding staff causes medication incidents","A correlation driven by a lurking variable such as patient volume","Proof that incidents cause managers to add staff","A non-linear relationship that r cannot detect"],answer:1,hint:"What else rises on a busy day?",steps:[{title:"Key idea",body:"Patient volume raises **both** staffing and incidents, so they correlate without one causing the other."},{title:"Eliminate look-alikes",body:"Neither direction of cause is proven; the pattern is linear, not curved."}],final:"Lurking variable (patient volume) → answer **B**",whyWrong:["Incorrect — correlation from historical data cannot prove cause and effect.","","Incorrect — reverse causation is also unproven; a third factor explains both counts.","Incorrect — r = 0.89 shows a strong straight-line pattern, not a hidden curve."],bookRef:"Book p. 431"},{id:"sv-4-349",phase:4,topic:"4.1.1",qtype:"scenario",difficulty:2,stem:'A logistics Green Belt finds **r = 0.83** (p = 0.000) between **truck load (t)** and **fuel used per trip (L)**. The manager asks: "How many extra litres do we use for each extra tonne?" Which analysis answers this question?',options:["A second Pearson correlation with more trips","A chi-square test of independence","Simple linear regression","A paired t-test"],answer:2,hint:"Litres per tonne is a rate of change of Y per unit of X.",steps:[{title:"Key idea",body:"Correlation gives **strength**; regression gives the **equation**, whose slope is the change in Y per unit X."},{title:"Apply to the stem",body:"Litres per extra tonne = the slope of fuel on load → simple linear regression."}],final:"Regression gives the slope → answer **C**",whyWrong:["Incorrect — r gives strength only; more data would not turn it into litres per tonne.","Incorrect — chi-square is for attribute counts, not continuous load and fuel.","","Incorrect — a paired t-test compares two measurements on the same units, not a rate of change."],bookRef:"Book pp. 432–433"},{id:"sv-4-350",phase:4,topic:"4.1.1",qtype:"scenario",difficulty:1,stem:"A team deliberately runs a bakery oven at **three set temperatures** while holding batch size and proofing time fixed, and records loaf volume at each setting. What is this an example of?",options:["A correlation analysis of historical data","A process capability study","A measurement system analysis","A designed experiment"],answer:3,hint:"Was X observed or set by the team?",steps:[{title:"Key idea",body:"Setting X at chosen levels and holding other factors constant is **experimentation (DOE)**."},{title:"Eliminate look-alikes",body:"Correlation is passive and historical — the book says it is not experimentation."}],final:"Designed experiment → answer **D**",whyWrong:["Incorrect — correlation observes existing records; here X is changed on purpose.","Incorrect — capability compares process spread with specification limits.","Incorrect — MSA studies the measurement system, not the effect of temperature.",""],bookRef:"Book p. 447"},{id:"sv-4-351",phase:4,topic:"4.1.1",qtype:"scenario",difficulty:3,stem:"In a warehouse, 25 days of data give **r = 0.79** between **pick errors** and **dock temperature**. One day, when the scanner system failed, has extreme values on both. Without that day, r = 0.08. What should the Black Belt conclude?",options:["The correlation is driven by one unusual point that must be investigated","Temperature is a proven cause of pick errors","The relationship is strong because r with all data exceeds 0.70","The extreme day should be deleted and the result reported as r = 0.79"],answer:0,hint:"What happens to r when the one extreme day is removed?",steps:[{title:"Key idea",body:"An **influential outlier** can create a correlation on its own."},{title:"Apply to the stem",body:"r drops from 0.79 to 0.08 without the scanner-failure day, so that day drives the result."},{title:"Eliminate look-alikes",body:"Investigate the special cause; do not claim cause or a strong link."}],final:"One influential point → answer **A**",whyWrong:["","Incorrect — correlation never proves cause, and here it depends on a single day.","Incorrect — the strength disappears without one point, so it is not a stable relationship.","Incorrect — deleting the point gives r = 0.08, not 0.79; outliers should be investigated, not hidden."],bookRef:"Book pp. 428–432"},{id:"sv-4-352",phase:4,topic:"4.1.1",qtype:"best-action",difficulty:2,stem:"From 18 months of production records, a Black Belt found **r = 0.86** (p = 0.000) between **line speed** and **scrap rate**. She immediately cut line speed on all lines. Was this an appropriate action, and why?",options:["Yes, because |r| above 0.80 proves that line speed causes scrap","Yes, because p < 0.05 shows that slowing the line will reduce scrap","No, because correlation does not prove that line speed causes scrap","No, because r must exceed 0.95 before any action is taken"],answer:2,hint:"What does historical correlation not prove?",steps:[{title:"Key idea",body:"Correlation on historical data shows association; a lurking variable may drive both."},{title:"Apply to the stem",body:"Before changing X, cause must be confirmed — for example by a designed experiment or pilot."}],final:"No — correlation is not causation → answer **C**",whyWrong:["Incorrect — |r| > 0.80 shows practical strength of association, never proof of cause.","Incorrect — a small P-Value shows the association is real, not that changing X will change Y.","","Incorrect — there is no 0.95 rule; the problem is cause, not the size of r."],bookRef:"Book p. 431"},{id:"sv-4-353",phase:4,topic:"4.1.1",qtype:"best-action",difficulty:3,stem:"Using 900 claims, a Black Belt finds **r = 0.12** (P-Value = 0.003) between **form length** and **processing days**. She recommends a large project to shorten all forms. Was this an appropriate recommendation, and why?",options:["Yes, because a P-Value below 0.05 proves the relationship is important","Yes, because a large sample guarantees practical significance","No, because a P-Value below 0.05 means no relationship exists","No, because the relationship is significant but too weak to be useful"],answer:3,hint:"Statistical significance and practical significance are separate checks.",steps:[{title:"Key idea",body:"p = 0.003 < 0.05 → statistically significant. |r| = 0.12 < 0.20 → **not practically significant**."},{title:"Apply to the stem",body:"Form length explains very little of processing time, so a big project on it is poorly justified."}],final:"No — significant but too weak → answer **D**",whyWrong:["Incorrect — a small P-Value shows the correlation is real, not that it is large.","Incorrect — a large sample makes weak correlations significant; it does not make them useful.","Incorrect — p < α means H₀: ρ = 0 is rejected, so a relationship does exist.",""],bookRef:"Book pp. 430–431"},{id:"sv-4-354",phase:4,topic:"4.1.1",qtype:"best-action",difficulty:1,stem:"A Black Belt has 50 paired readings of **oven temperature** and **coating thickness**. What should she do FIRST before calculating the correlation coefficient?",options:["Fit a quadratic regression model","Plot the pairs on a scatter plot","Run a designed experiment on temperature","Remove the points that lie far from the trend"],answer:1,hint:"Recall the first step of the book's regression roadmap.",steps:[{title:"Key idea",body:"Book order: **scatter plot → correlation → fitted line → regression**."},{title:"Eliminate look-alikes",body:"Regression and DOE come later; deleting points blindly hides information."}],final:"Scatter plot first → answer **B**",whyWrong:["Incorrect — regression comes after the scatter plot and correlation in the book's roadmap.","","Incorrect — a DOE is not a prerequisite for correlating historical pairs.","Incorrect — points should never be removed before they are seen and investigated."],bookRef:"Book p. 449"},{id:"sv-4-355",phase:4,topic:"4.1.1",qtype:"best-action",difficulty:3,stem:"Engineers know from physics that **tablet hardness** rises with **compression force**. A Black Belt's correlation from 15 batches, all made within a narrow force window, gives **r = 0.45** with **P-Value = 0.09** (α = 0.05). What is the BEST next action?",options:["Conclude that force and hardness are not related","Accept the null hypothesis that the correlation is zero","Collect more paired data across a wider range of force before concluding","Use the correlation to set the compression force"],answer:2,hint:"Small n plus a narrow X range weakens the test.",steps:[{title:"Key idea",body:"p = 0.09 ≥ 0.05 → **fail to reject H₀** — not enough evidence, which is different from 'no relationship'."},{title:"Apply to the stem",body:"A narrow force window (restricted range) and only 15 batches hide a known effect."},{title:"Eliminate look-alikes",body:"Widen the range of X and add data before deciding."}],final:"Collect more data over a wider range → answer **C**",whyWrong:["Incorrect — failing to reject H₀ is not proof of no relationship, especially with a narrow X range.","Incorrect — the correct wording is 'fail to reject H₀'; we never accept it.","","Incorrect — r gives no equation, and here it is not even significant."],bookRef:"Book pp. 428–432",trap:"'Fail to reject H₀' never means 'accept H₀'."},{id:"sv-4-356",phase:4,topic:"4.1.1",qtype:"output",difficulty:2,stem:`A Black Belt correlates **mould temperature (°C)** with **shrinkage (%)** for 30 parts (α = 0.05):

\`\`\`
Correlation: Mould_Temp, Shrinkage

Pearson correlation   -0.812
P-value                0.000
\`\`\`

Which conclusion is CORRECT?`,options:["The correlation is weak because r is below zero","There is no significant correlation because r is negative","Higher mould temperature is proven to reduce shrinkage","There is a significant, strong negative linear correlation"],answer:3,hint:"Read p for the decision, the sign for direction and |r| for strength.",steps:[{title:"Key idea",body:"p = 0.000 < 0.05 → reject H₀: ρ = 0."},{title:"Apply to the stem",body:"r = −0.812: negative direction, |r| > 0.80 → strong."},{title:"Eliminate look-alikes",body:"Negative ≠ weak, and correlation ≠ cause."}],final:"Significant strong negative correlation → answer **D**",whyWrong:["Incorrect — the sign shows direction only; |−0.812| is above 0.80, so it is strong.","Incorrect — significance comes from p = 0.000 < 0.05, not from the sign of r.","Incorrect — correlation on observed data shows association, not proof of cause.",""],bookRef:"Book pp. 428–432"},{id:"sv-4-357",phase:4,topic:"4.1.1",qtype:"output",difficulty:2,stem:`A bank Green Belt checks **loan amount** against **approval days** for 10 applications (α = 0.05):

\`\`\`
Correlation: Loan_Amount, Approval_Days

Pearson correlation   0.580
P-value               0.079
\`\`\`

Which conclusion is CORRECT?`,options:["Fail to reject H₀; there is not enough evidence of a linear correlation","Accept H₀; loan amount and approval days are proven to be unrelated","Reject H₀; there is a significant moderate positive correlation","The correlation is practically significant because r is above 0.50"],answer:0,hint:"Compare p with α before looking at r.",steps:[{title:"Key idea",body:"p = 0.079 ≥ 0.05 → **fail to reject H₀: ρ = 0**."},{title:"Apply to the stem",body:"With only 10 pairs, r = 0.58 could arise by chance."},{title:"Eliminate look-alikes",body:"Never 'accept H₀'; 0.50 is not the practical threshold."}],final:"Fail to reject H₀ → answer **A**",whyWrong:["","Incorrect — the exam wording is 'fail to reject', and a non-significant result proves nothing.","Incorrect — p = 0.079 is above α = 0.05, so H₀ cannot be rejected.","Incorrect — the book's practical guideline is |r| above 0.80, not 0.50."],bookRef:"Book pp. 428–432"},{id:"sv-4-358",phase:4,topic:"4.1.1",qtype:"output",difficulty:2,stem:`A Black Belt correlates **carton weight** with **sealing time** for 14 runs:

\`\`\`
Correlation: Carton_Weight, Seal_Time

Pearson correlation   0.927
P-value               0.000
\`\`\`

A colleague writes: "The P-Value is high at 0.927, so the correlation is not significant." Which correction is CORRECT?`,options:["0.927 is the P-Value, so the correlation is significant only at α = 0.95","0.927 is r; the P-Value is 0.000, so the correlation is significant","0.927 is R-sq, so 92.7% of the variation in sealing time is explained","0.927 is the slope, so sealing time rises 0.927 units per unit of weight"],answer:1,hint:"Read which label sits next to each number.",steps:[{title:"Key idea",body:"'Pearson correlation' = **r = 0.927**; 'P-value' = **0.000**."},{title:"Apply to the stem",body:"p = 0.000 < 0.05 → significant; |r| > 0.80 → also strong."},{title:"Eliminate look-alikes",body:"The book itself once mislabels r as the P-Value — a known trap."}],final:"0.927 is r; p = 0.000 → answer **B**",whyWrong:["Incorrect — the P-Value is printed on its own line as 0.000; 0.927 is the Pearson coefficient.","","Incorrect — the Pearson line shows r, not R-sq; R-sq is reported in regression output.","Incorrect — a correlation output gives r, not a slope; the slope comes from regression."],bookRef:"Book pp. 428–432",trap:"Do not mix up r and the P-Value — check the label on each line."},{id:"sv-4-359",phase:4,topic:"4.1.1",qtype:"output",difficulty:3,stem:`For an early screening of causes, the team agreed to use **α = 0.10**. Output for **ambient humidity (%)** versus **paint adhesion score**, 20 panels:

\`\`\`
Correlation: Humidity, Adhesion

Pearson correlation   -0.410
P-value                0.073
\`\`\`

Which conclusion is CORRECT?`,options:["Fail to reject H₀ because the P-Value is above 0.05","Reject H₀ and conclude the relationship is practically strong","Reject H₀ at α = 0.10; there is evidence of a negative linear correlation","Fail to reject H₀ because r is negative"],answer:2,hint:"Compare p with the α the team agreed, not with a habit value.",steps:[{title:"Key idea",body:"Decision rule: **p < α → reject H₀**."},{title:"Apply to the stem",body:"p = 0.073 < 0.10 → reject H₀; r = −0.41 → negative, moderate."},{title:"Eliminate look-alikes",body:"Do not swap in 0.05, and do not call |r| = 0.41 strong."}],final:"Reject H₀ at α = 0.10 → answer **C**",whyWrong:["Incorrect — the agreed α is 0.10, not 0.05; p = 0.073 is below 0.10.","Incorrect — |−0.41| is in the book's grey zone, well below the 0.80 'strong' guideline.","","Incorrect — the sign of r has nothing to do with the decision."],bookRef:"Book pp. 428–432"},{id:"sv-4-360",phase:4,topic:"4.1.1",qtype:"output",difficulty:3,stem:`A warehouse Green Belt runs a correlation matrix for 30 shifts (α = 0.05):

\`\`\`
Correlation: Pick_Rate, Aisle_Length, Order_Lines

              Pick_Rate  Aisle_Length
Aisle_Length     -0.684
                  0.000

Order_Lines       0.231        0.105
                  0.219        0.581

Cell Contents: Pearson correlation
               P-Value
\`\`\`

Which conclusion is CORRECT?`,options:["Pick rate has significant correlations with both aisle length and order lines","Order lines has the strongest correlation with pick rate","Aisle length and order lines are significantly correlated with each other","Pick rate has a significant negative correlation with aisle length only"],answer:3,hint:"Each cell shows r on top and its P-Value underneath.",steps:[{title:"Key idea",body:"Read the cell contents: top = r, bottom = P-Value."},{title:"Apply to the stem",body:"Pick_Rate–Aisle_Length: r = −0.684, p = 0.000 → significant negative. Pick_Rate–Order_Lines: p = 0.219 → not significant."},{title:"Eliminate look-alikes",body:"The order-lines cells are both non-significant."}],final:"Only aisle length is significant → answer **D**",whyWrong:["Incorrect — order lines versus pick rate has p = 0.219 > 0.05, so it is not significant.","Incorrect — |0.231| is smaller than |−0.684|, and it is not significant.","Incorrect — aisle length versus order lines has r = 0.105 and p = 0.581, not significant.",""],bookRef:"Book pp. 428–432"},{id:"sv-4-361",phase:4,topic:"4.1.1",qtype:"true-false",difficulty:1,stem:"A correlation coefficient of **r = −0.90** means that Y tends to decrease as X increases. True or False?",options:["True","False"],answer:0,hint:"The sign of r gives the direction.",steps:[{title:"Key idea",body:"Negative r → Y tends to **decrease** as X increases."},{title:"Apply to the stem",body:"The statement matches the meaning of a negative sign, so it is true."}],final:"Negative r: Y falls as X rises → answer **True**",whyWrong:["","Incorrect — a negative r means a negative relationship: Y tends to fall as X rises."],bookRef:"Book pp. 428–432"},{id:"sv-4-362",phase:4,topic:"4.1.1",qtype:"sequence",difficulty:2,stem:`Order these correlation coefficients from the **weakest** to the **strongest** linear relationship:

- **P** — r = +0.35
- **Q** — r = −0.92
- **R** — r = +0.10
- **S** — r = −0.60`,options:["R, P, S, Q","Q, S, R, P","R, P, Q, S","P, R, S, Q"],answer:0,hint:"Rank by |r|, ignoring the sign.",steps:[{title:"Key idea",body:"Strength = **|r|**: 0.10, 0.35, 0.60, 0.92."},{title:"Apply to the stem",body:"That is R, P, S, Q."}],final:"R, P, S, Q → answer **A**",whyWrong:["","Incorrect — this sorts r by signed value (most negative first) instead of by strength |r|.","Incorrect — |−0.92| is larger than |−0.60|, so Q must come last.","Incorrect — |+0.10| is smaller than |+0.35|, so R must come before P."],bookRef:"Book pp. 428–432"},{id:"sv-4-363",phase:4,topic:"4.1.1",qtype:"sequence",difficulty:1,stem:`Put these steps of a correlation hypothesis test in the correct order:

- **P** — Compare the P-Value with α and state the conclusion
- **Q** — State H₀: ρ = 0 and Hₐ: ρ ≠ 0
- **R** — Run the correlation in Minitab to get r and its P-Value
- **S** — Choose the significance level α`,options:["R, Q, S, P","Q, S, R, P","S, R, P, Q","Q, R, S, P"],answer:1,hint:"Decide the rules before you look at the result.",steps:[{title:"Key idea",body:"Hypotheses → α → run the test → compare p with α."},{title:"Eliminate look-alikes",body:"Choosing α after seeing p would bias the decision."}],final:"Q, S, R, P → answer **B**",whyWrong:["Incorrect — the hypotheses and α must be set before the data are analysed.","","Incorrect — the hypotheses come first and the conclusion comes last.","Incorrect — α must be chosen before the result is seen, not after."],bookRef:"Book pp. 428–432"},{id:"sv-4-364",phase:4,topic:"4.1.2",qtype:"concept",difficulty:1,stem:"In the simple linear regression equation **Ŷ = b₀ + b₁X**, what is **b₁** called?",options:["The constant, or intercept","The residual of the model","The slope, or coefficient of X","The coefficient of determination"],answer:2,hint:"One term multiplies X; the other stands alone.",steps:[{title:"Key idea",body:"**b₀** = constant (intercept); **b₁** = coefficient of X (slope)."},{title:"Eliminate look-alikes",body:"Residuals and R-sq describe the fit, not the equation's terms."}],final:"b₁ = slope → answer **C**",whyWrong:["Incorrect — the constant (intercept) is b₀, the predicted Y when X = 0.","Incorrect — a residual is the gap between an observed Y and its fitted value.","","Incorrect — the coefficient of determination is R-sq, not a term in the equation."],bookRef:"Book pp. 432–438"},{id:"sv-4-365",phase:4,topic:"4.1.2",qtype:"concept",difficulty:1,stem:"An assembly team's model is **Torque_Nm = 4.0 + 0.75 × Bolt_Diameter_mm**. What does **0.75** represent?",options:["The predicted torque, in N·m, when the bolt diameter is zero","The share of torque variation explained by bolt diameter","The correlation coefficient between torque and bolt diameter","The predicted increase in torque, in N·m, for each 1 mm increase in bolt diameter"],answer:3,hint:"The number multiplying X is a rate: units of Y per unit of X.",steps:[{title:"Key idea",body:"The slope b₁ is the **change in predicted Y for a one-unit increase in X**."},{title:"Apply to the stem",body:"0.75 N·m more torque predicted for every extra 1 mm of diameter."},{title:"Eliminate look-alikes",body:"4.0 = intercept; R-sq and r are different statistics."}],final:"Slope = 0.75 N·m per mm → answer **D**",whyWrong:["Incorrect — torque at zero diameter is the constant, 4.0.","Incorrect — the share of variation explained is R-sq, reported separately.","Incorrect — r is reported by a correlation; the slope depends on units, r does not.",""],bookRef:"Book pp. 432–438"},{id:"sv-4-366",phase:4,topic:"4.1.2",qtype:"concept",difficulty:2,stem:"On a fitted line plot, the points lie **very close** to the regression line. What does this indicate?",options:["R-sq is high and S is small","The slope is steep","The intercept is close to zero","The correlation is negative"],answer:0,hint:"Tight scatter around the line means small residuals.",steps:[{title:"Key idea",body:"Small residuals → most variation explained (**high R-sq**) and a small typical error (**small S**)."},{title:"Eliminate look-alikes",body:"Slope, intercept and direction do not describe the scatter."}],final:"Tight fit: high R-sq, small S → answer **A**",whyWrong:["","Incorrect — steepness is the slope; a shallow line can also fit tightly.","Incorrect — where the line crosses the Y axis says nothing about scatter.","Incorrect — the direction of the line is separate from how tight the fit is."],bookRef:"Book pp. 432–438"},{id:"sv-4-367",phase:4,topic:"4.1.2",qtype:"concept",difficulty:2,stem:"Which value in a simple regression output tells the team whether a **statistically significant** linear relationship exists between X and Y?",options:["R-sq","The P-Value for the X term (slope)","S","The coefficient of the constant"],answer:1,hint:"p tells WHETHER; R-sq tells HOW MUCH.",steps:[{title:"Key idea",body:"The slope's P-Value tests **H₀: b₁ = 0**; p < α → X is a significant predictor."},{title:"Eliminate look-alikes",body:"R-sq = how strong; S = typical error; constant = intercept."}],final:"Slope P-Value = whether → answer **B**",whyWrong:["Incorrect — R-sq tells how much variation is explained, not whether the slope differs from zero.","","Incorrect — S is the standard deviation of the residuals, a measure of typical error.","Incorrect — the constant is the intercept value; it does not test the X–Y relationship."],bookRef:"Book pp. 432–438",trap:"R-sq is not a significance test."},{id:"sv-4-368",phase:4,topic:"4.1.2",qtype:"concept",difficulty:1,stem:"In a simple linear regression, what does a slope of **zero** imply?",options:["The predicted value of Y is zero","Every point lies exactly on the line","Changing X has no linear effect on predicted Y","The intercept must also be zero"],answer:2,hint:"Slope = change in Y per unit of X.",steps:[{title:"Key idea",body:"b₁ = 0 → a flat line: predicted Y is the same whatever X is."},{title:"Eliminate look-alikes",body:"Zero slope says nothing about Y being zero, a perfect fit, or the intercept."}],final:"Zero slope = no linear effect → answer **C**",whyWrong:["Incorrect — with zero slope, predicted Y equals the intercept, which need not be zero.","Incorrect — a perfect fit is R-sq = 100%, unrelated to the slope value.","","Incorrect — the intercept is estimated separately and can take any value."],bookRef:"Book pp. 432–438"},{id:"sv-4-369",phase:4,topic:"4.1.2",qtype:"concept",difficulty:3,stem:"In the book's regression roadmap, which step comes **immediately after** checking the correlation?",options:["Analyse the residuals","Try quadratic or cubic models","Make a scatter plot","Run a fitted line plot"],answer:3,hint:"Recall: scatter → correlation → fitted line → regression → evaluate → non-linear → residuals.",steps:[{title:"Key idea",body:"Roadmap: 1 scatter plot, 2 correlation, **3 fitted line plot**, 4 regression, 5 R-sq/adj/p, 6 non-linear, 7 residuals."},{title:"Apply to the stem",body:"Step 3 follows step 2."}],final:"Fitted line plot → answer **D**",whyWrong:["Incorrect — residual analysis is the last step, used to validate the chosen model.","Incorrect — non-linear fits are tried only after the linear model has been evaluated.","Incorrect — the scatter plot is the first step, before correlation.",""],bookRef:"Book p. 449"},{id:"sv-4-370",phase:4,topic:"4.1.2",qtype:"concept",difficulty:1,stem:"Which equation is a **quadratic** (second-order) regression model?",options:["Y = a + bX + cX²","Y = a + bX","Y = a + bX + cX² + dX³","Y = a·bˣ"],answer:0,hint:"The order is the highest power of X.",steps:[{title:"Key idea",body:"Book list: linear Y = a + bX; **quadratic Y = a + bX + cX²**; cubic adds dX³; exponential Y = a·bˣ."},{title:"Apply to the stem",body:"Highest power 2 → quadratic."}],final:"Quadratic has X² → answer **A**",whyWrong:["","Incorrect — Y = a + bX is the linear (first-order) model.","Incorrect — a term in X³ makes it the cubic (third-order) model.","Incorrect — X in the exponent makes it the exponential model."],bookRef:"Book pp. 432–438"},{id:"sv-4-371",phase:4,topic:"4.1.2",qtype:"concept",difficulty:2,stem:"What does **R-sq = 0%** mean in a simple linear regression?",options:["Every point lies exactly on the fitted line","The model explains none of the variation in Y","The slope is highly significant","X is proven to cause Y"],answer:1,hint:"R-sq is the share of Y variation explained.",steps:[{title:"Key idea",body:"R-sq = SS Regression ÷ SS Total. **0%** → the line explains nothing; it is flat at Ȳ."},{title:"Eliminate look-alikes",body:"100% = perfect fit; significance and cause are separate questions."}],final:"R-sq 0% = nothing explained → answer **B**",whyWrong:["Incorrect — all points on the line is R-sq = 100%.","","Incorrect — with no variation explained, the slope is effectively zero and not significant.","Incorrect — no R-sq value proves cause; 0% shows no linear association at all."],bookRef:"Book pp. 432–438"},{id:"sv-4-372",phase:4,topic:"4.1.2",qtype:"concept",difficulty:2,stem:"Which statement about R-sq in a simple linear regression is CORRECT?",options:["An R-sq below 50% means the slope cannot be significant","R-sq is the P-Value of the regression expressed as a percentage","A high R-sq does not by itself show that the model is valid","R-sq increases when the prediction errors become larger"],answer:2,hint:"Fit statistics and model assumptions are different checks.",steps:[{title:"Key idea",body:"Residuals must also be checked: a high R-sq can hide curvature, outliers or non-constant variance."},{title:"Eliminate look-alikes",body:"R-sq ≠ p; low R-sq can coexist with a significant slope; bigger errors lower R-sq."}],final:"High R-sq is not enough → answer **C**",whyWrong:["Incorrect — with enough data a slope can be significant even when R-sq is low.","Incorrect — R-sq is the share of variation explained; the P-Value is a separate statistic.","","Incorrect — larger errors mean more unexplained variation, so R-sq falls."],bookRef:"Book pp. 437–438, 449"},{id:"sv-4-373",phase:4,topic:"4.1.2",qtype:"concept",difficulty:3,stem:"Which statement about a least-squares regression line is CORRECT?",options:["It always passes through the origin (0, 0)","It always passes through the point with the largest residual","It passes through every data point when R-sq is above 90%","It always passes through the point (X̄, Ȳ)"],answer:3,hint:"Recall the formula for the intercept: b₀ = Ȳ − b₁X̄.",steps:[{title:"Key idea",body:"Because **b₀ = Ȳ − b₁X̄**, putting X = X̄ into the equation gives Ŷ = Ȳ."},{title:"Eliminate look-alikes",body:"Origin needs b₀ = 0; a large residual is off the line; 90% is not a perfect fit."}],final:"Line passes through (X̄, Ȳ) → answer **D**",whyWrong:["Incorrect — the line passes through the origin only if the intercept happens to be zero.","Incorrect — the point with the largest residual is, by definition, far from the line.","Incorrect — only R-sq = 100% puts every point on the line.",""],bookRef:"Book pp. 432–438"},{id:"sv-4-374",phase:4,topic:"4.1.2",qtype:"concept",difficulty:2,stem:"Which statement about Minitab's regression **coefficients table** is CORRECT?",options:["Each term's T-Value is its coefficient divided by its SE Coef","The Constant row tests whether X is a significant predictor","SE Coef is the standard deviation of the Y data","A negative T-Value always means the term is not significant"],answer:0,hint:"T measures how many standard errors the coefficient is from zero.",steps:[{title:"Key idea",body:"Book: **T = Coef ÷ SE Coef**, and the P-Value comes from T."},{title:"Eliminate look-alikes",body:"Constant row ≠ test of X; SE Coef ≠ SD of Y; sign of T ≠ significance."}],final:"T = Coef ÷ SE Coef → answer **A**",whyWrong:["","Incorrect — the X row's P-Value judges X; the constant's P-Value is not used for that.","Incorrect — SE Coef is the standard error of the coefficient, not the spread of Y.","Incorrect — a negative T-Value comes from a negative coefficient; significance depends on its size."],bookRef:"Book pp. 432–438"},{id:"sv-4-375",phase:4,topic:"4.1.2",qtype:"statements",difficulty:3,stem:`Which statements about a simple regression output are CORRECT?

1. The constant's P-Value decides whether X is a useful predictor.
2. S is the percentage of variation in Y not explained by the model.
3. R-sq shows how much of the variation in Y the model explains.
4. The slope's P-Value shows whether X is a significant predictor.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:2,hint:"Check each output value against what it really measures.",steps:[{title:"Key idea",body:"R-sq = share explained (3, true). Slope P-Value = significance of X (4, true)."},{title:"Eliminate look-alikes",body:"1: constant's p is ignored for judging X. 2: S is the residual standard deviation, in Y units."}],final:"Statements 3 and 4 → answer **C**",whyWrong:["Incorrect — the constant's P-Value does not judge X, and S is a standard deviation, not a percentage.","Incorrect — statement 3 is true, but statement 2 confuses S with unexplained variation.","","Incorrect — statement 4 is true, but the constant's P-Value is not used to judge X."],bookRef:"Book pp. 432–438"},{id:"sv-4-376",phase:4,topic:"4.1.2",qtype:"statements",difficulty:3,stem:`Which two statements about using a regression equation are CORRECT?

1. The equation should be used only within the range of X in the data.
2. Residuals should be checked before the equation is relied on.
3. Predictions outside the X range are reliable when R-sq is high.
4. A significant slope proves that X causes Y.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:0,hint:"Two statements are good practice; two are classic traps.",steps:[{title:"Key idea",body:"Predict **within the X range** (1) and **validate with residuals** (2)."},{title:"Eliminate look-alikes",body:"3 = extrapolation trap; 4 = causation trap."}],final:"Statements 1 and 2 → answer **A**",whyWrong:["","Incorrect — statement 2 is true, but statement 3 extrapolates beyond the data.","Incorrect — statement 3 extrapolates and statement 4 treats association as cause.","Incorrect — statement 1 is true, but a significant slope on historical data does not prove cause."],bookRef:"Book pp. 434–438, 449"},{id:"sv-4-377",phase:4,topic:"4.1.2",qtype:"statements",difficulty:2,stem:`Which statements about the slope **b₁** in Ŷ = b₀ + b₁X are CORRECT?

1. Its sign always matches the sign of the correlation coefficient r.
2. It shows the share of variation in Y explained by X.
3. It is the predicted value of Y when X equals zero.
4. It gives the change in predicted Y for a one-unit increase in X.`,options:["1 and 2","2 and 3","3 and 4","1 and 4"],answer:3,hint:"Separate the slope from the intercept and from R-sq.",steps:[{title:"Key idea",body:"b₁ = change in Ŷ per unit of X (4); its sign equals the sign of r (1)."},{title:"Eliminate look-alikes",body:"2 = R-sq; 3 = b₀."}],final:"Statements 1 and 4 → answer **D**",whyWrong:["Incorrect — statement 1 is true, but the share of variation explained is R-sq.","Incorrect — statement 2 describes R-sq and statement 3 describes the intercept.","Incorrect — statement 4 is true, but statement 3 describes the intercept b₀.",""],bookRef:"Book pp. 432–438"},{id:"sv-4-378",phase:4,topic:"4.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

Minitab fits a regression line by the method of least [?], which makes the sum of the squared residuals as small as possible.`,options:["absolute","medians","squares","variance"],answer:2,hint:"The name of the method says what is minimised.",steps:[{title:"Key idea",body:"The best-fit line minimises the **sum of squared residuals** → method of **least squares**."},{title:"Eliminate look-alikes",body:"The other words do not name the regression fitting method."}],final:"least squares → answer **C**",whyWrong:["Incorrect — least absolute deviations is a different fitting method, not the one Minitab uses here.","Incorrect — medians belong to non-parametric tests, not to fitting the regression line.","","Incorrect — 'least variance' is not the name of the method, although it reduces error."],bookRef:"Book pp. 432–438"},{id:"sv-4-379",phase:4,topic:"4.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

In regression, the output Y is also called the [?] variable.`,options:["dependent","independent","lurking","nuisance"],answer:0,hint:"Y depends on X.",steps:[{title:"Key idea",body:"**X = independent** (input, predictor); **Y = dependent** (output, response)."},{title:"Eliminate look-alikes",body:"Lurking and nuisance variables are not the modelled output."}],final:"dependent → answer **A**",whyWrong:["","Incorrect — the independent variable is X, the input or predictor.","Incorrect — a lurking variable is a hidden third factor outside the model.","Incorrect — a nuisance variable is an uncontrolled input that adds noise."],bookRef:"Book pp. 428–429"},{id:"sv-4-380",phase:4,topic:"4.1.2",qtype:"missing-word",difficulty:1,stem:`Identify the missing word in the following sentence.

[?] is the percentage of the total variation in Y that is explained by the regression model.`,options:["P-Value","R-sq","S","T-Value"],answer:1,hint:"Which statistic is reported as a percentage of variation?",steps:[{title:"Key idea",body:"**R-sq = SS Regression ÷ SS Total**, shown as a percentage."},{title:"Eliminate look-alikes",body:"P-Value = significance; S = typical error; T = Coef ÷ SE Coef."}],final:"R-sq → answer **B**",whyWrong:["Incorrect — the P-Value shows whether a term or the model is significant.","","Incorrect — S is the standard deviation of the residuals.","Incorrect — the T-Value is a coefficient divided by its standard error."],bookRef:"Book pp. 432–438"},{id:"sv-4-381",phase:4,topic:"4.1.2",qtype:"not-except",difficulty:3,stem:"A simple regression gives a slope P-Value of **0.002** (α = 0.05). Which conclusion is NOT valid from this value alone?",options:["The null hypothesis that the slope is zero is rejected","The model explains most of the variation in Y","X is a statistically significant linear predictor of Y","The regression equation is statistically significant"],answer:1,hint:"The P-Value says WHETHER, not HOW MUCH.",steps:[{title:"Key idea",body:"A small P-Value shows the slope is not zero."},{title:"Apply to the stem",body:"How much variation is explained is R-sq, which could still be low."}],final:"p does not tell how much is explained → answer **B**",whyWrong:["Valid — p = 0.002 < 0.05, so H₀: b₁ = 0 is rejected; this is not the answer.","","Valid — a significant slope means X is a significant predictor; this is not the answer.","Valid — in simple regression the slope test and the ANOVA test agree; this is not the answer."],bookRef:"Book pp. 432–438",trap:"A significant slope can come with a low R-sq."},{id:"sv-4-382",phase:4,topic:"4.1.2",qtype:"not-except",difficulty:3,stem:"A fitted line plot from a chemical plant shows **Yield_% = 62.0 + 1.25 × Catalyst_g** with **R-sq = 81%**, fitted to runs with 2–10 g of catalyst. Which statement is NOT correct?",options:["Each extra gram of catalyst adds 1.25 percentage points to predicted yield","A prediction at 30 g of catalyst would be an extrapolation","81% of the variation in catalyst amount is explained by yield","The model explains 81% of the variation in yield"],answer:2,hint:"R-sq describes the response Y, not the predictor.",steps:[{title:"Key idea",body:"R-sq = share of variation **in Y** explained by X."},{title:"Apply to the stem",body:"The first option reverses the roles of X and Y, so it is the false statement."}],final:"R-sq is about Y, not X → answer **C**",whyWrong:["Correct statement — 1.25 is the slope in yield points per gram; this is not the answer.","Correct statement — 30 g is outside the 2–10 g range; this is not the answer.","","Correct statement — R-sq refers to variation in Y, the yield; this is not the answer."],bookRef:"Book pp. 432–438"},{id:"sv-4-383",phase:4,topic:"4.1.2",qtype:"scenario",difficulty:1,stem:"A bakery Green Belt wants to predict **loaf moisture (%)** from **baking time (min)**. In Minitab's Fitted Line Plot dialog, what should she enter as the **Response (Y)**?",options:["Baking time","The residuals","The batch number","Loaf moisture"],answer:3,hint:"The response is what you want to predict.",steps:[{title:"Key idea",body:"**Response = Y**, the output to be predicted; **Predictor = X**, the input."},{title:"Apply to the stem",body:"She wants to predict moisture → moisture is the response."}],final:"Response = loaf moisture → answer **D**",whyWrong:["Incorrect — baking time is the input used to predict moisture, so it is the predictor (X).","Incorrect — residuals are produced by the model; they are not entered as Y.","Incorrect — a batch number is an identifier, not the output being predicted.",""],bookRef:"Book pp. 432–434"},{id:"sv-4-384",phase:4,topic:"4.1.2",qtype:"scenario",difficulty:1,stem:"A hotel Green Belt wants an equation that predicts **room-cleaning time (min)** from **room size (m²)**. She has 60 rooms with both values measured. Which analysis should she use?",options:["Simple linear regression","One-way ANOVA","Chi-square test of independence","Two-sample t-test"],answer:0,hint:"Continuous X, continuous Y, and an equation wanted.",steps:[{title:"Key idea",body:"Continuous X and Y + a **prediction equation** → **simple linear regression**."},{title:"Eliminate look-alikes",body:"ANOVA and t-tests need group X's; chi-square needs counts."}],final:"Simple linear regression → answer **A**",whyWrong:["","Incorrect — one-way ANOVA compares means across groups of a categorical X.","Incorrect — chi-square tests association between two attribute variables.","Incorrect — a two-sample t-test compares the means of two groups."],bookRef:"Book pp. 432–438"},{id:"sv-4-385",phase:4,topic:"4.1.2",qtype:"scenario",difficulty:1,stem:"A logistics team models **delivery cost (OMR)** on **route distance (km)**. In what units is the **slope** of this model?",options:["km per OMR","OMR per km","OMR","Percent of variation explained"],answer:1,hint:"Slope = change in Y per one unit of X.",steps:[{title:"Key idea",body:"The slope is in **units of Y per unit of X**."},{title:"Apply to the stem",body:"Y = cost (OMR), X = distance (km) → OMR per km."}],final:"OMR per km → answer **B**",whyWrong:["Incorrect — that would be the slope of distance on cost, with X and Y swapped.","","Incorrect — OMR alone is the unit of the intercept (cost at zero distance).","Incorrect — a percentage of variation explained is R-sq, not the slope."],bookRef:"Book pp. 432–438"},{id:"sv-4-386",phase:4,topic:"4.1.2",qtype:"scenario",difficulty:3,stem:"From 4,000 meter-reading routes, a utility Green Belt finds that each extra kilometre adds **0.4 seconds** to route time (slope P-Value = 0.000). Average route time is about 3 hours. She proposes redesigning all routes to shorten them. What is the BEST view of this result?",options:["The effect is large because the P-Value is 0.000","The slope is not significant because 0.4 is less than 1","The effect is statistically significant but too small to matter in practice","Distance is proven to be the main cause of long routes"],answer:2,hint:"Statistical significance and practical size are different questions.",steps:[{title:"Key idea",body:"With thousands of points, even a tiny slope gives p < 0.05."},{title:"Apply to the stem",body:"0.4 s per km against a 3-hour route is negligible — **statistically, not practically, significant**."},{title:"Eliminate look-alikes",body:"Judge practical impact from the size of the slope."}],final:"Significant but negligible → answer **C**",whyWrong:["Incorrect — a tiny P-Value shows the slope is not zero, not that it is large.","Incorrect — significance comes from the P-Value, not from the slope being above or below 1.","","Incorrect — historical regression shows association only, and this effect is tiny."],bookRef:"Book pp. 432–438"},{id:"sv-4-387",phase:4,topic:"4.1.2",qtype:"scenario",difficulty:2,stem:"A validated model predicts **cooling time** from **part thickness**, built from parts 2–8 mm thick. Engineering asks for the predicted cooling time of a new **5 mm** part made of the same material on the same line. What is this use of the model?",options:["An extrapolation that should be avoided","A designed experiment","A correlation analysis","An interpolation that is appropriate"],answer:3,hint:"Is the new X inside or outside the data range?",steps:[{title:"Key idea",body:"Predicting **inside** the X range = interpolation; **outside** = extrapolation."},{title:"Apply to the stem",body:"5 mm is within 2–8 mm, same material and line → an appropriate interpolation."}],final:"Interpolation → answer **D**",whyWrong:["Incorrect — 5 mm lies inside the 2–8 mm range, so it is not an extrapolation.","Incorrect — no factor is being set deliberately; the model is being used to predict.","Incorrect — correlation measures strength; this is a prediction from the equation.",""],bookRef:"Book pp. 432–438"},{id:"sv-4-388",phase:4,topic:"4.1.2",qtype:"best-action",difficulty:2,stem:"A Black Belt's regression of **seal strength** on **jaw temperature** gives **R-sq = 92%** and a slope P-Value of 0.000. Without looking at the residuals, she uses the equation to set the jaw temperature. Was this an appropriate action, and why?",options:["Yes, because R-sq above 90% shows the model assumptions are met","Yes, because a P-Value of 0.000 makes residual checks unnecessary","No, because the residuals must be checked to validate the model","No, because an R-sq above 90% usually indicates an error in the data"],answer:2,hint:"What is the last step of the roadmap?",steps:[{title:"Key idea",body:"Roadmap step 7: **analyse residuals** to validate the model."},{title:"Apply to the stem",body:"High R-sq and small p do not replace that check."}],final:"No — residuals not checked → answer **C**",whyWrong:["Incorrect — a high R-sq can still hide curvature, outliers or non-constant variance.","Incorrect — a significant slope does not confirm the assumptions behind the model.","","Incorrect — a high R-sq is not a sign of data error; the issue is the skipped validation."],bookRef:"Book p. 449"},{id:"sv-4-389",phase:4,topic:"4.1.2",qtype:"best-action",difficulty:3,stem:"Regression output for **dispatch time** on **parcels per route** shows the constant with P-Value **0.47** and the parcels term with P-Value **0.000** (α = 0.05). The Black Belt keeps parcels per route as a significant predictor. Was this an appropriate action, and why?",options:["Yes, because the slope's P-Value shows that parcels per route is significant","Yes, because a constant P-Value above 0.05 confirms the model is valid","No, because the constant's P-Value above 0.05 makes the model unusable","No, because both P-Values must be below 0.05 before X is kept"],answer:0,hint:"Which row of the coefficients table tests X?",steps:[{title:"Key idea",body:"Read the **X term's** P-Value to judge X; the book says the constant's p does not matter for that."},{title:"Apply to the stem",body:"0.000 < 0.05 → parcels per route is significant, so keeping it is correct."}],final:"Yes — read the slope's P-Value → answer **A**",whyWrong:["","Incorrect — the constant's P-Value says nothing about the model's validity.","Incorrect — the constant's P-Value is not used to decide whether X is useful.","Incorrect — only the X term's P-Value judges whether X is a significant predictor."],bookRef:"Book pp. 432–438"},{id:"sv-4-390",phase:4,topic:"4.1.2",qtype:"best-action",difficulty:2,stem:'A Black Belt writes in her report: "R-sq = 85%, so 85% of the yield is caused by reactor temperature." Was this an appropriate statement, and why?',options:["Yes, because R-sq measures how much of Y is caused by X","Yes, because an R-sq above 80% proves cause and effect","No, because R-sq is the share of yield variation explained, not proof of cause","No, because R-sq should be read as the probability that the model is wrong"],answer:2,hint:"R-sq is about variation explained.",steps:[{title:"Key idea",body:"R-sq = % of the **variation in Y** explained by the model."},{title:"Apply to the stem",body:"Regression on historical data shows association only, so 'caused by' over-claims."}],final:"No — explained, not caused → answer **C**",whyWrong:["Incorrect — R-sq measures variation explained, not cause.","Incorrect — no R-sq value proves cause; that needs a designed experiment.","","Incorrect — R-sq is not a probability; the P-Value is the probability-based statistic."],bookRef:"Book pp. 432–438"},{id:"sv-4-391",phase:4,topic:"4.1.2",qtype:"output",difficulty:2,stem:`A Black Belt regresses **cure time (min)** on **coating thickness (mm)** for 24 panels (α = 0.05):

\`\`\`
Regression Analysis: Cure_min versus Thickness_mm

Coefficients
Term            Coef  SE Coef  T-Value  P-Value
Constant        4.20     1.10     3.82    0.001
Thickness_mm    2.35     0.28     8.39    0.000

Model Summary
      S    R-sq  R-sq(adj)
 1.9420  76.2%     75.1%
\`\`\`

Which conclusion is CORRECT?`,options:["Thickness is a significant predictor and explains about 76% of the variation in cure time","Thickness explains about 76% of cure time, so the remaining 24% is measurement error","Thickness is not significant because its T-Value is greater than 2","Cure time explains about 76% of the variation in thickness"],answer:0,hint:"Read the X term's P-Value, then R-sq.",steps:[{title:"Key idea",body:"Thickness P-Value = 0.000 < 0.05 → significant."},{title:"Apply to the stem",body:"R-sq = 76.2% → about 76% of the variation in cure time is explained."},{title:"Eliminate look-alikes",body:"Unexplained ≠ only gauge error; R-sq is about Y."}],final:"Significant; R-sq ≈ 76% → answer **A**",whyWrong:["","Incorrect — unexplained variation includes all other X's and noise, not only measurement error.","Incorrect — a large T-Value gives a small P-Value; 0.000 < 0.05 shows significance.","Incorrect — R-sq describes variation in the response Y (cure time), not in X."],bookRef:"Book pp. 432–438"},{id:"sv-4-392",phase:4,topic:"4.1.2",qtype:"output",difficulty:2,stem:`A food plant regresses **fill weight (g)** on **line speed (packs/min)** for 28 runs (α = 0.05):

\`\`\`
Regression Analysis: Fill_g versus Line_Speed

Coefficients
Term          Coef  SE Coef  T-Value  P-Value
Constant    498.20     0.95   524.42    0.000
Line_Speed   0.064    0.071     0.90    0.376

Model Summary
      S    R-sq  R-sq(adj)
 0.8130   3.0%      0.0%
\`\`\`

Which conclusion is CORRECT?`,options:["Line speed is significant because the constant's P-Value is 0.000","There is no evidence that line speed is a significant predictor of fill weight","Line speed is proven to have no effect on fill weight","Each extra pack per minute adds 0.064 g, so speed should be used to control fill"],answer:1,hint:"Which row tests X, and how does its P-Value compare with α?",steps:[{title:"Key idea",body:"Line_Speed P-Value = 0.376 > 0.05 → **fail to reject H₀: b₁ = 0**."},{title:"Apply to the stem",body:"R-sq = 3% confirms line speed explains almost nothing."},{title:"Eliminate look-alikes",body:"Ignore the constant's p; 'not significant' ≠ 'proven no effect'."}],final:"Line speed not significant → answer **B**",whyWrong:["Incorrect — the constant's P-Value does not test X; the Line_Speed row does (p = 0.376).","","Incorrect — failing to reject H₀ is not proof of no effect.","Incorrect — the slope is not significant, so 0.064 g could be zero."],bookRef:"Book pp. 432–438"},{id:"sv-4-393",phase:4,topic:"4.1.2",qtype:"output",difficulty:3,stem:`A Black Belt regresses **customer wait time (min)** on **queue length** for 40 periods (α = 0.05):

\`\`\`
Coefficients
Term          Coef  SE Coef  T-Value  P-Value
Constant     21.50     3.90     5.51    0.000
Queue_Len     0.85     0.38     2.24    0.031

Model Summary
      S    R-sq  R-sq(adj)
 6.1120  11.6%      9.3%
\`\`\`

Which statement is CORRECT?`,options:["Queue length is not significant because R-sq is below 50%","Queue length explains most of the variation because its P-Value is below 0.05","Queue length is a significant predictor, but most of the variation in wait time is unexplained","The model is significant only because the constant's P-Value is 0.000"],answer:2,hint:"p says WHETHER; R-sq says HOW MUCH.",steps:[{title:"Key idea",body:"Queue_Len p = 0.031 < 0.05 → significant."},{title:"Apply to the stem",body:"R-sq = 11.6% → about 88% of the variation comes from other X's or noise."},{title:"Eliminate look-alikes",body:"The team should look for further X's before relying on this model."}],final:"Significant but weak → answer **C**",whyWrong:["Incorrect — significance is judged from the P-Value (0.031), not from the size of R-sq.","Incorrect — a small P-Value shows the slope is not zero, not that it explains much.","","Incorrect — the constant's P-Value does not test the model or X."],bookRef:"Book pp. 432–438",trap:"Do not read R-sq as a significance test."},{id:"sv-4-394",phase:4,topic:"4.1.2",qtype:"output",difficulty:2,stem:`A hotel Green Belt fits a regression of **cleaning time** on **room size**:

\`\`\`
Coefficients
Term        Coef  SE Coef  T-Value  P-Value
Constant    6.40     1.85     3.46    0.002
Room_m2    0.482    0.061     7.90    0.000
\`\`\`

Which regression equation matches this output?`,options:["Clean_min = 0.482 + 6.40 Room_m2","Clean_min = 1.85 + 0.061 Room_m2","Clean_min = 3.46 + 7.90 Room_m2","Clean_min = 6.40 + 0.482 Room_m2"],answer:3,hint:"The equation uses the Coef column.",steps:[{title:"Key idea",body:"Equation = **Constant Coef + (X Coef) × X**."},{title:"Apply to the stem",body:"Constant 6.40, Room_m2 0.482 → Clean_min = 6.40 + 0.482 Room_m2."},{title:"Eliminate look-alikes",body:"SE Coef and T-Value columns are not equation terms."}],final:"Use the Coef column → answer **D**",whyWrong:["Incorrect — the constant and slope have been swapped.","Incorrect — these are the standard errors (SE Coef), not the coefficients.","Incorrect — these are the T-Values, not the coefficients.",""],bookRef:"Book pp. 432–438"},{id:"sv-4-395",phase:4,topic:"4.1.2",qtype:"sequence",difficulty:1,stem:`Order these regression models from the **lowest** to the **highest** order:

- **P** — Y = a + bX + cX² + dX³
- **Q** — Y = a + bX
- **R** — Y = a + bX + cX²`,options:["Q, R, P","P, R, Q","R, Q, P","Q, P, R"],answer:0,hint:"Order = highest power of X.",steps:[{title:"Key idea",body:"Linear = 1st order, quadratic = 2nd, cubic = 3rd."},{title:"Apply to the stem",body:"So Q, R, P."}],final:"Q, R, P → answer **A**",whyWrong:["","Incorrect — this runs from highest to lowest order.","Incorrect — the linear model (first order) has a lower order than the quadratic.","Incorrect — the cubic (X³) is the highest order, so it must come last."],bookRef:"Book pp. 432–438"},{id:"sv-4-396",phase:4,topic:"4.1.2",qtype:"sequence",difficulty:2,stem:`Four candidate predictors of **claim processing time** were each fitted in a separate simple regression. Order them from the **least** to the **most** variation in Y explained:

| Predictor | R-sq |
|---|---:|
| **P** — Pages in claim | 45.2% |
| **Q** — Handler tenure | 12.4% |
| **R** — Number of approvals | 88.1% |
| **S** — Documents missing | 67.5% |`,options:["R, S, P, Q","Q, P, S, R","Q, S, P, R","P, Q, S, R"],answer:1,hint:"R-sq = share of variation in Y explained.",steps:[{title:"Key idea",body:"Read R-sq: 12.4% < 45.2% < 67.5% < 88.1%."},{title:"Apply to the stem",body:"So Q, P, S, R."}],final:"Q, P, S, R → answer **B**",whyWrong:["Incorrect — this runs from most to least variation explained.","","Incorrect — 45.2% is less than 67.5%, so P comes before S.","Incorrect — 12.4% is the smallest R-sq, so Q comes first."],bookRef:"Book pp. 432–438"},{id:"sv-4-397",phase:4,topic:"4.1.2",qtype:"concept",difficulty:1,stem:"On a fitted line plot, where is the **intercept** b₀ shown?",options:["Where the fitted line crosses the horizontal (X) axis","At the point with the largest residual","Where the fitted line crosses the vertical (Y) axis at X = 0","At the right-hand end of the fitted line"],answer:2,hint:"b₀ is the predicted Y when X = 0.",steps:[{title:"Key idea",body:"Put X = 0 in Ŷ = b₀ + b₁X → Ŷ = b₀: the height of the line at **X = 0**."},{title:"Eliminate look-alikes",body:"X-axis crossing, residuals and line ends are not the intercept."}],final:"Intercept = Y-axis crossing → answer **C**",whyWrong:["Incorrect — crossing the X axis is where predicted Y = 0, not the intercept.","Incorrect — a large residual marks a point far from the line, not a model term.","","Incorrect — the end of the line depends only on the largest X value in the data."],bookRef:"Book pp. 432–438"},{id:"sv-4-398",phase:4,topic:"4.1.2",qtype:"concept",difficulty:3,stem:"Two packaging lines both give **R-sq = 85%**, but one slope is 0.2 and the other is 3.5. How can this happen?",options:["R-sq is always equal to the slope written as a percentage","A steeper slope must always give a higher R-sq","Equal R-sq values prove that the two slopes are equal","R-sq measures how tightly points fit the line, while the slope measures the rate of change of Y"],answer:3,hint:"Fit quality and steepness are different properties.",steps:[{title:"Key idea",body:"**R-sq** = share of Y variation explained (tightness). **Slope** = change in Y per unit X (steepness)."},{title:"Apply to the stem",body:"Both lines fit equally tightly, but Y changes at very different rates."},{title:"Eliminate look-alikes",body:"Neither statistic can be read from the other."}],final:"Fit ≠ steepness → answer **D**",whyWrong:["Incorrect — R-sq is a share of variation explained; it is not derived from the slope value.","Incorrect — a steep line can have wide scatter and a shallow line a tight fit.","Incorrect — R-sq says nothing about how steep the line is.",""],bookRef:"Book pp. 432–438"},{id:"sv-4-399",phase:4,topic:"4.1.2",qtype:"concept",difficulty:2,stem:"In a regression ANOVA table, what does **SS Error** represent?",options:["The variation in Y that the regression model does not explain","The variation in Y that the regression model explains","The total variation of Y around its mean","The variation in X around its mean"],answer:0,hint:"SS Total splits into an explained part and an unexplained part.",steps:[{title:"Key idea",body:"**SS Total = SS Regression (explained) + SS Error (unexplained)**."},{title:"Apply to the stem",body:"SS Error is the sum of squared residuals — what the line leaves unexplained."}],final:"SS Error = unexplained variation → answer **A**",whyWrong:["","Incorrect — explained variation is SS Regression.","Incorrect — total variation is SS Total, the sum of the two parts.","Incorrect — the ANOVA table splits the variation of Y, not of X."],bookRef:"Book pp. 432–438"},{id:"sv-4-400",phase:4,topic:"4.1.2",qtype:"concept",difficulty:1,stem:"In regression, what is the **predictor**?",options:["The output variable Y that is being predicted","The input variable X used to predict Y","The difference between an observed and a fitted value","The percentage of variation the model explains"],answer:1,hint:"It does the predicting.",steps:[{title:"Key idea",body:"Predictor = **X** (input, regressor); response = **Y** (output)."},{title:"Eliminate look-alikes",body:"Residual and R-sq describe the fit, not a variable."}],final:"Predictor = X → answer **B**",whyWrong:["Incorrect — the output being predicted is the response.","","Incorrect — observed minus fitted is a residual.","Incorrect — the percentage explained is R-sq."],bookRef:"Book pp. 432–434"},{id:"sv-4-401",phase:4,topic:"4.1.2",qtype:"concept",difficulty:1,stem:"How is the **sign of the slope** b₁ used when interpreting a regression?",options:["By showing whether the slope is statistically significant","By showing how much of the variation in Y is explained","By showing whether predicted Y rises or falls as X increases","By showing whether the residuals are normally distributed"],answer:2,hint:"Positive slope up, negative slope down.",steps:[{title:"Key idea",body:"b₁ > 0 → Y rises with X; b₁ < 0 → Y falls as X rises. Its sign always matches r."},{title:"Eliminate look-alikes",body:"Significance, R-sq and residual checks come from other parts of the output."}],final:"Sign = direction → answer **C**",whyWrong:["Incorrect — significance is judged from the slope's P-Value.","Incorrect — the share of variation explained is R-sq.","","Incorrect — residual normality is checked with residual plots."],bookRef:"Book pp. 432–438"},{id:"sv-4-402",phase:4,topic:"4.1.2",qtype:"concept",difficulty:1,stem:"What is another name for **R-sq** in regression output?",options:["The correlation coefficient","The coefficient of variation","The regression coefficient","The coefficient of determination"],answer:3,hint:"It 'determines' how much of Y the model accounts for.",steps:[{title:"Key idea",body:"R-sq is the **coefficient of determination**: the share of Y variation explained."},{title:"Eliminate look-alikes",body:"r, the coefficient of variation and the b's are different statistics."}],final:"Coefficient of determination → answer **D**",whyWrong:["Incorrect — the correlation coefficient is r; R-sq equals r² only in simple regression.","Incorrect — the coefficient of variation is a standard deviation divided by a mean.","Incorrect — regression coefficients are b₀ and b₁ in the equation.",""],bookRef:"Book pp. 432–438"},{id:"sv-4-403",phase:4,topic:"4.1.2",qtype:"concept",difficulty:3,stem:"A regression of **checkout time** on **cashier age** has a slope P-Value of **0.64**. Without other information, what is the best prediction of checkout time for any cashier?",options:["The overall mean checkout time","The intercept of the fitted equation","The value given by the fitted equation for that cashier's age","The largest checkout time in the data"],answer:0,hint:"If X does not help, what is the best single estimate of Y?",steps:[{title:"Key idea",body:"p = 0.64 → **fail to reject H₀: b₁ = 0** — no evidence that age helps predict checkout time."},{title:"Apply to the stem",body:"With no useful X, the best estimate of Y is its **mean**, Ȳ."},{title:"Eliminate look-alikes",body:"Look for other X's rather than using a non-significant equation."}],final:"Use the mean of Y → answer **A**",whyWrong:["","Incorrect — the intercept is the prediction only at age 0 and has no special status.","Incorrect — the slope is not significant, so the equation adds nothing reliable over the mean.","Incorrect — the maximum is an extreme value, not a typical prediction."],bookRef:"Book pp. 432–438"},{id:"sv-4-404",phase:4,topic:"4.1.2",qtype:"concept",difficulty:3,stem:"A real linear relationship exists between X and Y. A Black Belt adds more data points from the **same stable process** and refits the regression. What is expected to happen to the slope's P-Value?",options:["It tends to become larger","It tends to become smaller","It stays exactly the same","It becomes equal to R-sq"],answer:1,hint:"The P-Value depends on both the effect and the sample size.",steps:[{title:"Key idea",body:"More data → smaller standard error of the slope → larger |T| → **smaller P-Value**."},{title:"Eliminate look-alikes",body:"R-sq stays about the same; it is a different measure."}],final:"More data → smaller p → answer **B**",whyWrong:["Incorrect — more data from a real relationship strengthens the evidence, so p falls rather than rises.","","Incorrect — the P-Value depends on n, so it changes as data are added.","Incorrect — the P-Value and R-sq are different statistics."],bookRef:"Book pp. 432–438"},{id:"sv-4-405",phase:4,topic:"4.1.2",qtype:"concept",difficulty:2,stem:"Which statement about regressing Y on X versus regressing X on Y is CORRECT?",options:["Both the correlation r and the regression equations are the same","The correlation changes sign, but the equations are the same","The correlation r is the same, but the two regression equations differ","The regression of X on Y always has the higher R-sq"],answer:2,hint:"Least squares minimises the vertical errors in the response only.",steps:[{title:"Key idea",body:"r treats X and Y alike, but least squares minimises errors **in the response**, so the equation depends on which is Y."},{title:"Apply to the stem",body:"Choose Y as the output to be predicted; do not swap roles."}],final:"Same r, different equations → answer **C**",whyWrong:["Incorrect — r is symmetric, but each equation minimises errors in a different variable.","Incorrect — swapping the variables does not change the sign of r.","","Incorrect — in simple regression R-sq = r², so both fits have the same R-sq."],bookRef:"Book pp. 432–434"},{id:"sv-4-406",phase:4,topic:"4.1.2",qtype:"concept",difficulty:2,stem:"Which statement about how a regression splits the variation in Y into parts is CORRECT?",options:["SS Error is split into SS Regression and SS Total","SS Regression is always smaller than SS Error","SS Total depends only on the values of X","SS Total is split into SS Regression and SS Error"],answer:3,hint:"Total = explained + unexplained.",steps:[{title:"Key idea",body:"**SS Total = SS Regression + SS Error**, and R-sq = SS Regression ÷ SS Total."},{title:"Eliminate look-alikes",body:"SS Total measures Y, and either part can be the larger."}],final:"SS Total = SSR + SSE → answer **D**",whyWrong:["Incorrect — SS Error is one part of the split, not the whole.","Incorrect — a good model has SS Regression much larger than SS Error.","Incorrect — SS Total is the variation of Y around its mean.",""],bookRef:"Book pp. 432–438"},{id:"sv-4-407",phase:4,topic:"4.1.2",qtype:"best-action",difficulty:3,stem:"A hospital model is **Stay_days = 1.2 + 0.8 × Comorbidities**, fitted to patients with 0 to 6 comorbidities. A manager reports that patients with **no comorbidities** are predicted to stay about 1.2 days. Was this an appropriate interpretation, and why?",options:["Yes, because the intercept is the predicted Y at X = 0 and X = 0 lies within the data","Yes, because the intercept is always meaningful whatever the data range","No, because the intercept can never be interpreted in a regression","No, because 1.2 is the slope and not the predicted length of stay"],answer:0,hint:"When does b₀ have a practical meaning?",steps:[{title:"Key idea",body:"b₀ = predicted Y when X = 0."},{title:"Apply to the stem",body:"Patients with 0 comorbidities were in the data, so 1.2 days is a valid interpolation."}],final:"Yes — X = 0 is in range → answer **A**",whyWrong:["","Incorrect — if X = 0 lies outside the data, the intercept is an extrapolation and may mean nothing.","Incorrect — the intercept can be interpreted when X = 0 is inside the range studied.","Incorrect — 0.8 is the slope; 1.2 is the constant (intercept)."],bookRef:"Book pp. 432–438"},{id:"sv-4-408",phase:4,topic:"4.1.2",qtype:"scenario",difficulty:2,stem:"A Black Belt wants to model whether a **weld passes or fails** inspection (Pass / Fail) from **weld current (A)**. A colleague suggests a simple linear regression. What is the main problem with this suggestion?",options:["The response is attribute data, but simple linear regression needs a continuous Y","Weld current is continuous, so it cannot be used as a predictor","Simple linear regression needs at least two predictors","Pass/Fail data must always be analysed with a control chart first"],answer:0,hint:"Check the data type of Y.",steps:[{title:"Key idea",body:"Simple linear regression needs **continuous X and continuous Y**."},{title:"Apply to the stem",body:"Pass / Fail is a binary attribute response, so a linear equation for Y is not suitable."},{title:"Eliminate look-alikes",body:"The predictor is fine; the response type is the problem."}],final:"Attribute Y → answer **A**",whyWrong:["","Incorrect — a continuous X is exactly what simple linear regression uses as a predictor.","Incorrect — simple regression has one predictor; two or more is multiple regression.","Incorrect — control charts monitor stability; they do not model Y = f(X)."],bookRef:"Book pp. 428–434"},{id:"sv-4-409",phase:4,topic:"4.1.2",qtype:"output",difficulty:2,stem:`Two packing lines were studied separately (α = 0.05):

\`\`\`
Line A: Seal_s = 1.40 + 0.520 Film_um   P(slope) = 0.000   R-sq = 79.6%
Line B: Seal_s = 1.85 + 0.210 Film_um   P(slope) = 0.000   R-sq = 84.1%
\`\`\`

Which statement is CORRECT?`,options:["Line A has the stronger fit because its slope is larger","On Line A, sealing time rises more for each extra micron of film","Film thickness is significant on Line A only","Line B's sealing time does not depend on film thickness"],answer:1,hint:"Slope = rate of change; R-sq = tightness of fit; p = significance.",steps:[{title:"Key idea",body:"Compare slopes for **rate**: 0.520 s per µm (A) versus 0.210 s per µm (B)."},{title:"Apply to the stem",body:"Line A changes more per micron; Line B fits slightly more tightly; both are significant."}],final:"Line A has the larger slope → answer **B**",whyWrong:["Incorrect — fit is judged by R-sq, and Line B has the higher R-sq (84.1%).","","Incorrect — both slope P-Values are 0.000, so film is significant on both lines.","Incorrect — Line B's slope is significant; it is just smaller."],bookRef:"Book pp. 432–438"},{id:"sv-4-410",phase:4,topic:"4.1.2",qtype:"output",difficulty:2,stem:`Regression of **kitting time (min)** on **parts per kit**, 32 kits:

\`\`\`
Coefficients
Term       Coef  SE Coef  T-Value  P-Value
Constant   8.60     1.90     4.53    0.000
Parts     1.740    0.150    11.60    0.000

Model Summary
      S    R-sq  R-sq(adj)
 2.3100  81.8%     81.2%
\`\`\`

The Champion asks: (1) "Is there a real relationship?" and (2) "How much of the variation in kitting time does part count explain?" Which values answer these two questions?`,options:["(1) R-sq of 81.8%; (2) the Parts P-Value of 0.000","(1) S of 2.31; (2) R-sq(adj) of 81.2%","(1) the Parts P-Value of 0.000; (2) R-sq of 81.8%","(1) the Constant P-Value of 0.000; (2) the Parts coefficient of 1.740"],answer:2,hint:"p says WHETHER; R-sq says HOW MUCH.",steps:[{title:"Key idea",body:"The X term's P-Value tests H₀: b₁ = 0 → **whether** a relationship exists."},{title:"Apply to the stem",body:"R-sq = 81.8% → **how much** of the variation is explained."},{title:"Eliminate look-alikes",body:"S, the constant row and the coefficient answer other questions."}],final:"P-Value then R-sq → answer **C**",whyWrong:["Incorrect — the two statistics are swapped: R-sq measures how much, the P-Value whether.","Incorrect — S is the typical prediction error; it does not test whether a relationship exists.","","Incorrect — the constant's P-Value does not test X, and the coefficient is a rate, not a share."],bookRef:"Book pp. 432–438"},{id:"sv-4-411",phase:4,topic:"4.1.2",qtype:"output",difficulty:3,stem:`A plant regresses **energy use (MWh)** on **output (t)** for 20 days, with output between **150 and 400 t**:

\`\`\`
Regression Equation
Energy = -12.5 + 0.840 Output_t

Coefficients
Term        Coef  SE Coef  T-Value  P-Value
Constant   -12.5      6.8    -1.84    0.083
Output_t   0.840    0.026    32.31    0.000

Model Summary
R-sq = 98.3%
\`\`\`

A manager says the negative constant proves the model is wrong because energy cannot be negative. Which response is CORRECT?`,options:["The manager is right; a valid model must have a positive constant","The constant's P-Value of 0.083 shows that output is not a significant predictor","The negative constant means energy falls as output rises","The constant is the prediction at 0 t, which lies far outside the data, so it needs no physical meaning"],answer:3,hint:"Where is X = 0 compared with the data range?",steps:[{title:"Key idea",body:"b₀ = predicted Y at X = 0. Here X = 0 t is far below the 150–400 t range."},{title:"Apply to the stem",body:"The intercept only positions the line; within 150–400 t the model fits well (R-sq 98.3%, p = 0.000)."},{title:"Eliminate look-alikes",body:"The constant's p does not judge X; the slope's sign gives direction."}],final:"Intercept outside range — no meaning needed → answer **D**",whyWrong:["Incorrect — a negative intercept is common when X = 0 is outside the range studied.","Incorrect — X is judged by its own row: Output_t P-Value = 0.000.","Incorrect — direction comes from the slope, which is positive (0.840).",""],bookRef:"Book pp. 432–438"},{id:"sv-4-412",phase:4,topic:"4.1.2",qtype:"not-except",difficulty:2,stem:"Which value is NOT shown in Minitab's regression **Model Summary**?",options:["The P-Value of the slope","S","R-sq","R-sq(adj)"],answer:0,hint:"The Model Summary describes fit; tests are elsewhere.",steps:[{title:"Key idea",body:"Model Summary = **S, R-sq, R-sq(adj)** (and R-sq(pred))."},{title:"Apply to the stem",body:"The slope's P-Value is in the **Coefficients** table (and the ANOVA table)."}],final:"Slope P-Value is in the Coefficients table → answer **A**",whyWrong:["","Shown — S, the residual standard deviation, is in the Model Summary; this is not the answer.","Shown — R-sq is in the Model Summary; this is not the answer.","Shown — R-sq(adj) is in the Model Summary; this is not the answer."],bookRef:"Book pp. 432–438"},{id:"sv-4-413",phase:4,topic:"4.1.2",qtype:"not-except",difficulty:3,stem:"A regression has a significant slope. Which is NOT a valid reason to distrust using the equation?",options:["The residuals versus fits plot shows a curved pattern","The slope is negative","Predictions are needed far outside the X range of the data","The process has changed since the data were collected"],answer:1,hint:"One option describes direction, not a problem.",steps:[{title:"Key idea",body:"A negative slope simply means Y falls as X rises — a valid model can have either sign."},{title:"Eliminate look-alikes",body:"Curved residuals, extrapolation and process change are real threats to the model."}],final:"Negative slope is not a problem → answer **B**",whyWrong:["A valid reason — a curved residual pattern means the linear model is the wrong shape; this is not the answer.","","A valid reason — extrapolation beyond the data range is risky; this is not the answer.","A valid reason — a model built on the old process may no longer hold; this is not the answer."],bookRef:"Book pp. 434–438, 449"},{id:"sv-4-414",phase:4,topic:"4.1.2",qtype:"sequence",difficulty:2,stem:`Four candidate X's for **invoice cycle time** were each tested in a separate simple regression. Order them from the **strongest** to the **weakest** statistical evidence of a relationship:

| Predictor | Slope P-Value |
|---|---:|
| **P** — Invoice lines | 0.240 |
| **Q** — Approvers | 0.001 |
| **R** — Supplier distance (km) | 0.048 |
| **S** — Missing fields | 0.000 |`,options:["P, R, Q, S","Q, S, R, P","S, Q, R, P","S, R, Q, P"],answer:2,hint:"The smaller the P-Value, the stronger the evidence against H₀.",steps:[{title:"Key idea",body:"Rank P-Values from smallest to largest: 0.000, 0.001, 0.048, 0.240."},{title:"Apply to the stem",body:"So S, Q, R, P. Note that P (0.240) is not significant at α = 0.05."}],final:"S, Q, R, P → answer **C**",whyWrong:["Incorrect — this runs from the weakest to the strongest evidence.","Incorrect — 0.000 is smaller than 0.001, so S comes before Q.","","Incorrect — 0.001 is smaller than 0.048, so Q comes before R."],bookRef:"Book pp. 432–438"},{id:"sv-4-415",phase:4,topic:"4.1.2",qtype:"true-false",difficulty:2,stem:"In a simple linear regression with **R-sq = 64%**, the slope must be positive. True or False?",options:["True","False"],answer:1,hint:"Squaring removes the sign.",steps:[{title:"Key idea",body:"In simple regression R-sq = r², which is never negative whatever the direction."},{title:"Apply to the stem",body:"The direction must be read from the slope (or r), so the statement is false."}],final:"R-sq carries no sign → answer **False**",whyWrong:["Incorrect — R-sq is a square, so it is the same for a positive or a negative slope.",""],bookRef:"Book pp. 432–438"}];export{e as items};
